1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_mcp.c
3	 *
4	 * MCP (Model Context Protocol) client side for the xiaozhi voice app.
5	 * See xiaozhi_mcp.h for an overview.
6	 *
7	 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
8	 *
9	 *   { "type": "mcp", "payload": <jsonrpc request> }
10	 *
11	 * This module is a *client*: it spawns a local MCP server ("mcp_server",
12	 * a built-in NuttX program) as a subprocess and forwards each cloud
13	 * request to it over the server's stdin pipe, then reads the server's
14	 * response from its stdout pipe and relays it back to the cloud as:
15	 *
16	 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
17	 *
18	 * The stdio transport uses newline-delimited JSON (one JSON-RPC object per
19	 * line, no embedded newlines), matching the MCP stdio spec and the
20	 * reference mcp-calculator-main/mcp_pipe.py bridge.
21	 *
22	 * SPDX-License-Identifier: Apache-2.0
23	 ****************************************************************************/
24	
25	#include <nuttx/config.h>
26	
27	#include <stdio.h>
28	#include <stdlib.h>
29	#include <string.h>
30	#include <stdbool.h>
31	#include <unistd.h>
32	#include <fcntl.h>
33	#include <spawn.h>
34	#include <errno.h>
35	
36	#include <netutils/cJSON.h>
37	
38	#include "xiaozhi_mcp.h"
39	
40	/****************************************************************************
41	 * Pre-processor Definitions
42	 ****************************************************************************/
43	
44	/* Name of the local MCP server built-in program to spawn. */
45	#define MCP_SERVER_PROGNAME  "mcp_server"
46	
47	/* Maximum length of one stdio JSON-RPC line (requests and responses). The
48	 * messages exchanged here are short; tools/list is the largest. */
49	#define MCP_LINE_MAX  4096
50	
51	/****************************************************************************
52	 * Private Types
53	 ****************************************************************************/
54	
55	/* State of the local MCP server subprocess and its stdin/stdout pipes. */
56	struct mcp_client_s
57	{
58	  bool   spawned;          /* server process has been started */
59	  pid_t  pid;              /* server process id */
60	  int    stdin_fd;         /* write end → server stdin  */
61	  int    stdout_fd;        /* read end  ← server stdout */
62	};
63	
64	/****************************************************************************
65	 * Private Data
66	 ****************************************************************************/
67	
68	static struct mcp_client_s g_client;
69	
70	/****************************************************************************
71	 * Private Functions
72	 ****************************************************************************/
73	
74	/* Send one JSON-RPC object as a newline-delimited line to the server stdin. */
75	static int client_write_request(cJSON *req)
76	{
77	  char *json = cJSON_PrintUnformatted(req);
78	  if (json == NULL)
79	    {
80	      return -ENOMEM;
81	    }
82	
83	  size_t len    = strlen(json);
84	  size_t total  = len + 1;          /* +1 for newline */
85	  int ret      = 0;
86	
87	  if (total > MCP_LINE_MAX)
88	    {
89	      free(json);
90	      return -E2BIG;
91	    }
92	
93	  /* Write the JSON followed by a newline. */
94	  if (write(g_client.stdin_fd, json, len) != (ssize_t)len)
95	    {
96	      ret = -EIO;
97	    }
98	  else if (write(g_client.stdin_fd, "\n", 1) != 1)
99	    {
100	      ret = -EIO;
101	    }
102	
103	  free(json);
104	  return ret;
105	}
106	
107	/* Read one newline-delimited JSON-RPC line from the server stdout and parse
108	 * it. Returns a cJSON object (caller frees) or NULL on error/EOF. */
109	static cJSON *client_read_response(void)
110	{
111	  char buf[MCP_LINE_MAX];
112	  size_t len = 0;
113	
114	  /* Read one byte at a time until newline or buffer full. MCP responses are
115	   * short; this is simple and avoids line-buffering subtleties. */
116	  while (len + 1 < sizeof(buf))
117	    {
118	      ssize_t n = read(g_client.stdout_fd, buf + len, 1);
119	      if (n <= 0)
120	        {
121	          /* EOF or error — server gone. */
122	          return NULL;
123	        }
124	
125	      if (buf[len] == '\n')
126	        {
127	          break;
128	        }
129	
130	      len++;
131	    }
132	
133	  if (len == 0)
134	    {
135	      return NULL;
136	    }
137	
138	  buf[len] = '\0';
139	  cJSON *resp = cJSON_Parse(buf);
140	  return resp;
141	}
142	
143	/* Tear down the server subprocess and close the pipes. */
144	static void client_teardown(void)
145	{
146	  if (g_client.stdin_fd >= 0)
147	    {
148	      close(g_client.stdin_fd);
149	      g_client.stdin_fd = -1;
150	    }
151	
152	  if (g_client.stdout_fd >= 0)
153	    {
154	      close(g_client.stdout_fd);
155	      g_client.stdout_fd = -1;
156	    }
157	
158	  g_client.spawned = false;
159	  g_client.pid     = 0;
160	}
161	
162	/* Spawn the local MCP server subprocess with stdin/stdout redirected to a
163	 * pair of pipes. Returns 0 on success, negative errno on failure. */
164	static int client_ensure_spawned(void)
165	{
166	  int to_server[2];     /* [0]=read (server stdin), [1]=write (client) */
167	  int from_server[2];   /* [0]=read (client),         [1]=write (server) */
168	  posix_spawn_file_actions_t actions;
169	  char *argv[2] = { (char *)MCP_SERVER_PROGNAME, NULL };
170	  int ret;
171	
172	  if (g_client.spawned)
173	    {
174	      return 0;
175	    }
176	
177	  if (pipe(to_server) != 0)
178	    {
179	      printf("[xiaozhi] mcp: to_server pipe failed: %d\n", errno);
180	      return -errno;
181	    }
182	
183	  if (pipe(from_server) != 0)
184	    {
185	      printf("[xiaozhi] mcp: from_server pipe failed: %d\n", errno);
186	      close(to_server[0]);
187	      close(to_server[1]);
188	      return -errno;
189	    }
190	
191	  ret = posix_spawn_file_actions_init(&actions);
192	  if (ret != 0)
193	    {
194	      goto fail_pipes;
195	    }
196	
197	  /* Server stdin  = read end of to_server pipe. */
198	  ret = posix_spawn_file_actions_adddup2(&actions, to_server[0], 0);
199	  if (ret != 0)
200	    {
201	      goto fail_actions;
202	    }
203	
204	  /* Server stdout = write end of from_server pipe. */
205	  ret = posix_spawn_file_actions_adddup2(&actions, from_server[1], 1);
206	  if (ret != 0)
207	    {
208	      goto fail_actions;
209	    }
210	
211	  /* Close the pipe ends the server does not need in its own fd table. */
212	  posix_spawn_file_actions_addclose(&actions, to_server[0]);
213	  posix_spawn_file_actions_addclose(&actions, to_server[1]);
214	  posix_spawn_file_actions_addclose(&actions, from_server[0]);
215	  posix_spawn_file_actions_addclose(&actions, from_server[1]);
216	
217	  ret = posix_spawn(&g_client.pid, MCP_SERVER_PROGNAME, &actions, NULL,
218	                    argv, NULL);
219	
220	  posix_spawn_file_actions_destroy(&actions);
221	
222	  if (ret != 0)
223	    {
224	      printf("[xiaozhi] mcp: posix_spawn(%s) failed: %d\n",
225	             MCP_SERVER_PROGNAME, ret);
226	      goto fail_pipes;
227	    }
228	
229	  /* Parent keeps the write end of to_server and the read end of from_server;
230	   * close the other ends. */
231	  close(to_server[0]);
232	  close(from_server[1]);
233	
234	  g_client.stdin_fd  = to_server[1];
235	  g_client.stdout_fd = from_server[0];
236	  g_client.spawned   = true;
237	
238	  printf("[xiaozhi] mcp: spawned %s (pid=%d)\n",
239	         MCP_SERVER_PROGNAME, g_client.pid);
240	  return 0;
241	
242	fail_actions:
243	  posix_spawn_file_actions_destroy(&actions);
244	
245	fail_pipes:
246	  close(to_server[0]);
247	  close(to_server[1]);
248	  close(from_server[0]);
249	  close(from_server[1]);
250	  return -ret;
251	}
252	
253	/* Forward a JSON-RPC request to the local server and relay its response
254	 * back as an "mcp" frame to the cloud. On any client/transport error, send
255	 * a JSON-RPC error response to the cloud instead. */
256	static void mcp_forward(struct xiaozhi_ws_s *ws, const char *session_id,
257	                        cJSON *req)
258	{
259	  int ret;
260	
261	  ret = client_ensure_spawned();
262	  if (ret != 0)
263	    {
264	      cJSON *err = cJSON_CreateObject();
265	      cJSON_AddStringToObject(err, "jsonrpc", "2.0");
266	      cJSON_AddItemReferenceToObject(err, "id", cJSON_GetObjectItem(req, "id"));
267	      cJSON_AddItemToObject(err, "error", cJSON_CreateObject());
268	      {
269	        cJSON *eobj = cJSON_GetObjectItem(err, "error");
270	        char msg[64];
271	        snprintf(msg, sizeof(msg),
272	                 "MCP server unavailable: %d", ret);
273	        cJSON_AddNumberToObject(eobj, "code", -32603);
274	        cJSON_AddStringToObject(eobj, "message", msg);
275	      }
276	
277	      /* Wrap the error in an mcp frame. */
278	      {
279	        cJSON *frame = cJSON_CreateObject();
280	        cJSON_AddStringToObject(frame, "type", "mcp");
281	        cJSON_AddStringToObject(frame, "session_id", session_id);
282	        cJSON_AddItemToObject(frame, "payload", err);
283	        char *j = cJSON_PrintUnformatted(frame);
284	        if (j != NULL)
285	          {
286	            xiaozhi_ws_send_text(ws, j, strlen(j));
287	            free(j);
288	          }
289	
290	        cJSON_Delete(frame);
291	      }
292	      return;
293	    }
294	
295	  ret = client_write_request(req);
296	  if (ret != 0)
297	    {
298	      printf("[xiaozhi] mcp: write to server failed: %d\n", ret);
299	      client_teardown();
300	      return;
301	    }
302	
303	  cJSON *resp = client_read_response();
304	  if (resp == NULL)
305	    {
306	      printf("[xiaozhi] mcp: no response from server\n");
307	      client_teardown();
308	      return;
309	    }
310	
311	  /* Wrap the server's JSON-RPC response in an mcp frame and send to cloud. */
312	  {
313	    cJSON *frame = cJSON_CreateObject();
314	    cJSON_AddStringToObject(frame, "type", "mcp");
315	    cJSON_AddStringToObject(frame, "session_id", session_id);
316	    cJSON_AddItemToObject(frame, "payload", resp);   /* frame owns resp */
317	    char *j = cJSON_PrintUnformatted(frame);
318	    if (j != NULL)
319	      {
320	        xiaozhi_ws_send_text(ws, j, strlen(j));
321	        free(j);
322	      }
323	
324	    cJSON_Delete(frame);
325	  }
326	}
327	
