329	 * Public Functions
330	 ****************************************************************************/
331	
332	void xiaozhi_mcp_add_features(cJSON *features)
333	{
334	  if (features == NULL)
335	    {
336	      return;
337	    }
338	
339	  cJSON_AddBoolToObject(features, "mcp", true);
340	}
341	
342	void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
343	                                const char *session_id,
344	                                cJSON *payload)
345	{
346	  cJSON *method = cJSON_GetObjectItem(payload, "method");
347	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
348	
349	  if (mstr == NULL)
350	    {
351	      printf("[xiaozhi] mcp: payload has no method\n");
352	      return;
353	    }
354	
355	  printf("[xiaozhi] mcp: forwarding method=%s\n", mstr);
356	
357	  /* Forward the request object verbatim to the local MCP server. */
358	  mcp_forward(ws, session_id, payload);
359	}
