1	/****************************************************************************
2	 * apps/examples/mcp_server/mcp_server_main.c
3	 *
4	 * A local MCP (Model Context Protocol) server speaking the stdio transport.
5	 * It exposes a single tool, "start_app", that launches a built-in NuttX
6	 * application on the device via posix_spawn().
7	 *
8	 * Transport (per the MCP stdio spec): messages are newline-delimited JSON-RPC
9	 * 2.0 objects — one request per line on stdin, one response per line on
10	 * stdout, no embedded newlines. stderr is used for logging only.
11	 *
12	 * This process is spawned by the xiaozhi_voice app, which acts as the MCP
13	 * client and forwards the cloud's MCP requests to this server over its
14	 * stdin/stdout pipes.
15	 *
16	 * SPDX-License-Identifier: Apache-2.0
17	 ****************************************************************************/
18	
19	#include <nuttx/config.h>
20	
21	#include <stdio.h>
22	#include <stdlib.h>
23	#include <string.h>
24	#include <stdbool.h>
25	#include <spawn.h>
26	#include <sys/wait.h>
27	#include <errno.h>
28	
29	#include <netutils/cJSON.h>
30	
31	/****************************************************************************
32	 * Pre-processor Definitions
33	 ****************************************************************************/
34	
35	#define MCP_PROTOCOL_VERSION "2024-11-05"
36	#define MCP_SERVER_NAME       "mcp-server"
37	#define MCP_SERVER_VERSION    "1.0"
38	
39	#define MCP_LINE_MAX  2048
40	
41	/* The fixed list of applications that can be launched. Each entry maps a
42	 * stable, human-friendly name to the NuttX builtin program name passed to
43	 * posix_spawn(). Extend this table to expose more apps.
44	 */
45	struct app_entry_s
46	{
47	  const char *name;   /* name exposed to the LLM via tools/list enum      */
48	  const char *prog;   /* builtin program name passed to posix_spawn()    */
49	};
50	
51	static const struct app_entry_s g_apps[] =
52	{
53	  { "hello", "hello" },
54	};
55	
56	#define APP_COUNT (sizeof(g_apps) / sizeof(g_apps[0]))
57	
58	/****************************************************************************
59	 * Private Function Prototypes
60	 ****************************************************************************/
61	
62	static cJSON *reply_result(cJSON *id);
63	static cJSON *reply_error(cJSON *id, int code, const char *message);
64	static void send_response(cJSON *resp);
65	static cJSON *handle_initialize(cJSON *id);
66	static cJSON *handle_tools_list(cJSON *id);
67	static cJSON *handle_tools_call(cJSON *id, cJSON *params);
68	static const struct app_entry_s *find_app(const char *name);
69	
70	/****************************************************************************
71	 * Private Functions
72	 ****************************************************************************/
73	
74	/* Build a JSON-RPC result object for the given request id. */
75	static cJSON *reply_result(cJSON *id)
76	{
77	  cJSON *resp = cJSON_CreateObject();
78	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
79	  cJSON_AddItemReferenceToObject(resp, "id", id);
80	  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
81	  return resp;
82	}
83	
84	/* Build a JSON-RPC error object for the given request id and code/message. */
85	static cJSON *reply_error(cJSON *id, int code, const char *message)
86	{
87	  cJSON *resp = cJSON_CreateObject();
88	  cJSON *err  = cJSON_CreateObject();
89	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
90	  cJSON_AddItemReferenceToObject(resp, "id", id);
91	  cJSON_AddItemToObject(resp, "error", err);
92	  cJSON_AddNumberToObject(err, "code", code);
93	  cJSON_AddStringToObject(err, "message", message);
94	  return resp;
95	}
96	
97	/* Serialize a JSON-RPC response as one line on stdout (newline-delimited). */
98	static void send_response(cJSON *resp)
99	{
100	  char *json = cJSON_PrintUnformatted(resp);
101	  if (json != NULL)
102	    {
103	      printf("%s\n", json);
104	      fflush(stdout);
105	      free(json);
106	    }
107	
108	  cJSON_Delete(resp);
109	}
110	
111	/* Build a single text content block (the shape tools/call results use). */
112	static cJSON *make_text_content(const char *text)
113	{
114	  cJSON *content = cJSON_CreateArray();
115	  cJSON *item    = cJSON_CreateObject();
116	  cJSON_AddItemToArray(content, item);
117	  cJSON_AddStringToObject(item, "type", "text");
118	  cJSON_AddStringToObject(item, "text", text);
119	  return content;
120	}
121	
122	static const struct app_entry_s *find_app(const char *name)
123	{
124	  for (size_t i = 0; i < APP_COUNT; i++)
125	    {
126	      if (strcmp(g_apps[i].name, name) == 0)
127	        {
128	          return &g_apps[i];
129	        }
130	    }
131	
132	  return NULL;
133	}
134	
135	/* initialize: report server info, protocol version, and capabilities. */
136	static cJSON *handle_initialize(cJSON *id)
137	{
138	  cJSON *resp     = reply_result(id);
139	  cJSON *result   = cJSON_GetObjectItem(resp, "result");
140	  cJSON *info     = cJSON_CreateObject();
141	  cJSON *caps     = cJSON_CreateObject();
142	  cJSON *toolscap = cJSON_CreateObject();
143	
144	  cJSON_AddStringToObject(result, "protocolVersion", MCP_PROTOCOL_VERSION);
145	  cJSON_AddItemToObject(result, "serverInfo", info);
146	  cJSON_AddStringToObject(info, "name", MCP_SERVER_NAME);
147	  cJSON_AddStringToObject(info, "version", MCP_SERVER_VERSION);
148	  cJSON_AddItemToObject(result, "capabilities", caps);
149	  cJSON_AddItemToObject(caps, "tools", toolscap);
150	  cJSON_AddBoolToObject(toolscap, "listChanged", false);
151	  return resp;
152	}
153	
154	/* tools/list: advertise the start_app tool and the app name enum. */
155	static cJSON *handle_tools_list(cJSON *id)
156	{
157	  cJSON *resp    = reply_result(id);
158	  cJSON *result  = cJSON_GetObjectItem(resp, "result");
159	  cJSON *tools  = cJSON_CreateArray();
160	  cJSON *tool   = cJSON_CreateObject();
161	  cJSON *schema = cJSON_CreateObject();
162	  cJSON *props  = cJSON_CreateObject();
163	  cJSON *apparg = cJSON_CreateObject();
164	  cJSON *reqd   = cJSON_CreateArray();
165	  cJSON *enumv  = cJSON_CreateArray();
166	
167	  cJSON_AddStringToObject(tool, "name", "start_app");
168	  cJSON_AddStringToObject(tool, "description",
169	    "启动设备上的一个应用。通过 app_name 指定要打开的应用，"
170	    "例如语音指令\"打开 hello 应用\"时调用此工具。");
171	  cJSON_AddItemToObject(tool, "inputSchema", schema);
172	
173	  cJSON_AddStringToObject(schema, "type", "object");
174	  cJSON_AddItemToObject(schema, "properties", props);
175	  cJSON_AddItemToObject(props, "app_name", apparg);
176	  cJSON_AddStringToObject(apparg, "type", "string");
177	  cJSON_AddStringToObject(apparg, "description", "要启动的应用名称");
178	  cJSON_AddItemToObject(apparg, "enum", enumv);
179	  for (size_t i = 0; i < APP_COUNT; i++)
180	    {
181	      cJSON_AddItemToArray(enumv, cJSON_CreateString(g_apps[i].name));
182	    }
183	
184	  cJSON_AddItemToObject(schema, "required", reqd);
185	  cJSON_AddItemToArray(reqd, cJSON_CreateString("app_name"));
186	
187	  cJSON_AddItemToArray(tools, tool);
188	  cJSON_AddItemToObject(result, "tools", tools);
189	  return resp;
190	}
191	
192	/* tools/call: dispatch by name. Only "start_app" is supported. */
193	static cJSON *handle_tools_call(cJSON *id, cJSON *params)
194	{
195	  cJSON *name = cJSON_GetObjectItem(params, "name");
196	  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;
197	
198	  if (namestr == NULL)
199	    {
200	      return reply_error(id, -32602, "Missing tool name");
201	    }
202	
203	  if (strcmp(namestr, "start_app") != 0)
204	    {
205	      return reply_error(id, -32601, "Unknown tool");
206	    }
207	
208	  cJSON *args     = cJSON_GetObjectItem(params, "arguments");
209	  cJSON *appname = (args != NULL) ? cJSON_GetObjectItem(args, "app_name") : NULL;
210	  const char *appstr = cJSON_IsString(appname) ? appname->valuestring : NULL;
211	
212	  if (appstr == NULL)
213	    {
214	      /* MCP convention: return an isError result so the LLM can react. */
215	      cJSON *resp     = reply_result(id);
216	      cJSON *result   = cJSON_GetObjectItem(resp, "result");
217	      cJSON_AddItemToObject(result, "content",
218	        make_text_content("Missing app_name argument"));
219	      cJSON_AddBoolToObject(result, "isError", true);
220	      return resp;
221	    }
222	
223	  const struct app_entry_s *app = find_app(appstr);
224	  if (app == NULL)
225	    {
226	      char msg[64];
227	      cJSON *resp;
228	      cJSON *result;
229	      snprintf(msg, sizeof(msg), "Unknown application: %s", appstr);
230	      resp   = reply_result(id);
231	      result = cJSON_GetObjectItem(resp, "result");
232	      cJSON_AddItemToObject(result, "content", make_text_content(msg));
233	      cJSON_AddBoolToObject(result, "isError", true);
234	      return resp;
235	    }
236	
237	  /* Launch the builtin application. argv[0] is the program name. */
238	  {
239	    char *argv[2] = { (char *)app->prog, NULL };
240	    pid_t pid;
241	    int ret = posix_spawn(&pid, app->prog, NULL, NULL, argv, NULL);
242	    if (ret != 0)
243	      {
244	        char msg[64];
245	        cJSON *resp;
246	        cJSON *result;
247	        snprintf(msg, sizeof(msg), "Failed to launch %s: %d", appstr, ret);
248	        resp   = reply_result(id);
249	        result = cJSON_GetObjectItem(resp, "result");
250	        cJSON_AddItemToObject(result, "content", make_text_content(msg));
251	        cJSON_AddBoolToObject(result, "isError", true);
252	        return resp;
253	      }
254	
255	    /* Don't wait — let the launched app run independently. */
256	    {
257	      char msg[64];
258	      cJSON *resp;
259	      cJSON *result;
260	      snprintf(msg, sizeof(msg), "已启动应用 %s", appstr);
261	      resp   = reply_result(id);
262	      result = cJSON_GetObjectItem(resp, "result");
263	      cJSON_AddItemToObject(result, "content", make_text_content(msg));
264	      cJSON_AddBoolToObject(result, "isError", false);
265	      return resp;
266	    }
267	  }
268	}
269	
270	/* Dispatch one JSON-RPC request object to a handler and return the response. */
271	static cJSON *dispatch(cJSON *req)
272	{
273	  cJSON *method = cJSON_GetObjectItem(req, "method");
274	  cJSON *id     = cJSON_GetObjectItem(req, "id");
275	  cJSON *params = cJSON_GetObjectItem(req, "params");
276	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
277	
278	  if (mstr == NULL)
279	    {
280	      return reply_error(id, -32600, "Missing method");
281	    }
282	
283	  if (strcmp(mstr, "initialize") == 0)
284	    {
285	      return handle_initialize(id);
286	    }
287	
288	  if (strcmp(mstr, "tools/list") == 0)
289	    {
290	      return handle_tools_list(id);
291	    }
292	
293	  if (strcmp(mstr, "tools/call") == 0)
294	    {
295	      return handle_tools_call(id, params ? params : cJSON_CreateObject());
296	    }
297	
298	  /* Notifications (no id) are not answered. */
299	  if (id == NULL)
300	    {
301	      return NULL;
302	    }
303	
304	  {
305	    char msg[80];
306	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
307	    return reply_error(id, -32601, msg);
308	  }
309	}
310	
311	/****************************************************************************
312	 * Public Functions
313	 ****************************************************************************/
314	
315	int main(int argc, FAR char *argv[])
316	{
317	  char line[MCP_LINE_MAX];
318	
319	  fprintf(stderr, "[mcp_server] started (stdio transport)\n");
320	
321	  /* Read newline-delimited JSON-RPC requests from stdin, one per line. */
322	  while (fgets(line, sizeof(line), stdin) != NULL)
323	    {
324	      /* Strip trailing newline. */
325	      size_t len = strlen(line);
326	      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
327	        {
328	          line[--len] = '\0';
329	        }
330	
331	      if (len == 0)
332	        {
333	          continue;
334	        }
335	
336	      cJSON *req = cJSON_Parse(line);
337	      if (req == NULL)
338	        {
339	          cJSON *resp = reply_error(NULL, -32700, "Parse error");
340	          send_response(resp);
341	          continue;
342	        }
343	
344	      cJSON *resp = dispatch(req);
345	      cJSON_Delete(req);
346	
347	      if (resp != NULL)
348	        {
349	          send_response(resp);
350	        }
351	    }
352	
353	  fprintf(stderr, "[mcp_server] stdin closed, exiting\n");
354	  return 0;
355	}
