/****************************************************************************
 * apps/examples/mcp_server/mcp_server_main.c
 *
 * A local MCP (Model Context Protocol) server speaking the stdio transport.
 * It exposes tools including:
 *   - "start_app": launch a built-in NuttX application via posix_spawn()
 *   - "set_timer":  set a countdown timer with optional message
 *   - "cancel_timer": cancel an active timer by id
 *   - "list_timers": list all active timers
 *
 * Transport (per the MCP stdio spec): messages are newline-delimited JSON-RPC
 * 2.0 objects — one request per line on stdin, one response per line on
 * stdout, no embedded newlines. stderr is used for logging only.
 *
 * This process is spawned by the xiaozhi_voice app, which acts as the MCP
 * client and forwards the cloud's MCP requests to this server over its
 * stdin/stdout pipes.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <spawn.h>
#include <sys/wait.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <netutils/cJSON.h>

#define APP_COUNT (sizeof(g_apps) / sizeof(g_apps[0]))

/* Timer definitions. */

#define TIMER_MAX_COUNT  8    /* maximum number of concurrent timers */
#define TIMER_MSG_MAX   128   /* maximum length of a timer message */

struct timer_s
{
  bool    active;              /* slot in use */
  int     id;                  /* unique timer id (1-based) */
  time_t  end_time;            /* absolute expiration time (epoch seconds) */
  char    message[TIMER_MSG_MAX]; /* user message (displayed on expiry) */
};

static struct timer_s g_timers[TIMER_MAX_COUNT];
static int g_next_timer_id = 1;

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

