/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  char line[MCP_LINE_MAX];
  time_t last_check = time(NULL);

  fprintf(stderr, "[mcp_server] started (stdio transport)\n");

  /* Set stdin to non-blocking mode for polling. */

  int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
  if (flags >= 0)
    {
      fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);
    }

  /* Main loop: poll stdin for requests and check timer expirations. */

  while (true)
    {
      /* Check for expired timers every second. */

      time_t now = time(NULL);
      if (now > last_check)
        {
          for (int i = 0; i < TIMER_MAX_COUNT; i++)
            {
              if (g_timers[i].active && now >= g_timers[i].end_time)
                {
                  fprintf(stderr,
                          "[mcp_server] TIMER %d EXPIRED: \"%s\"\n",
                          g_timers[i].id, g_timers[i].message);
                  g_timers[i].active = false;
                }
            }

          last_check = now;
        }

      /* Try to read a line from stdin (non-blocking). */

      ssize_t n = read(STDIN_FILENO, line, sizeof(line) - 1);
      if (n <= 0)
        {
          /* No data available or EOF. Sleep briefly and retry. */

          usleep(100000);  /* 100ms */
          continue;
        }

      /* Handle partial reads (line not yet complete). */

      if (line[n - 1] != '\n')
        {
          /* Keep reading until we get a newline. */

          size_t total = n;
          while (total < sizeof(line) - 1)
            {
              ssize_t more = read(STDIN_FILENO, line + total,
                                  sizeof(line) - 1 - total);
              if (more <= 0)
                {
                  break;
                }

              total += more;
              if (line[total - 1] == '\n')
                {
                  break;
                }
            }

          n = total;
        }

      /* Strip trailing newline. */

      size_t len = n;
      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
        {
          line[--len] = '\0';
        }

      if (len == 0)
        {
          continue;
        }

      cJSON *req = cJSON_Parse(line);
      if (req == NULL)
        {
          cJSON *resp = reply_error(NULL, -32700, "Parse error");
          send_response(resp);
          continue;
        }

      cJSON *resp = dispatch(req);
      cJSON_Delete(req);

      if (resp != NULL)
        {
          send_response(resp);
        }
    }

  fprintf(stderr, "[mcp_server] exiting\n");
  return 0;
}

