170	
171	/* Allocate a new timer slot. Returns NULL if no slot available. */
172	
173	static struct timer_s *timer_alloc(void)
174	{
175	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
176	    {
177	      if (!g_timers[i].active)
178	        {
179	          g_timers[i].active = true;
180	          g_timers[i].id = g_next_timer_id++;
181	          g_timers[i].end_time = 0;
182	          g_timers[i].message[0] = '\0';
183	          return &g_timers[i];
184	        }
185	    }
186	
187	  return NULL;
188	}
189	
190	/* Find a timer by id. Returns NULL if not found. */
191	
192	static struct timer_s *timer_find(int id)
193	{
194	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
195	    {
196	      if (g_timers[i].active && g_timers[i].id == id)
197	        {
198	          return &g_timers[i];
199	        }
200	    }
201	
202	  return NULL;
203	}
