215	/* Handle "set_timer" tool call.
216	 *   arguments:
217	 *     duration  (int, required) — seconds from now
218	 *     message   (string, optional) — message to display when timer expires
219	 *   Returns the timer id and remaining seconds.
220	 */
221	
222	static cJSON *handle_set_timer(cJSON *id, cJSON *params)
223	{
224	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
225	  if (args == NULL)
226	    {
227	      cJSON *resp   = reply_result(id);
228	      cJSON *result = cJSON_GetObjectItem(resp, "result");
229	      cJSON_AddItemToObject(result, "content",
230	        make_text_content("Missing arguments"));
231	      cJSON_AddBoolToObject(result, "isError", true);
232	      return resp;
233	    }
234	
235	  cJSON *dur_item = cJSON_GetObjectItem(args, "duration");
236	  if (!cJSON_IsNumber(dur_item))
237	    {
238	      cJSON *resp   = reply_result(id);
239	      cJSON *result = cJSON_GetObjectItem(resp, "result");
240	      cJSON_AddItemToObject(result, "content",
241	        make_text_content("Missing or invalid 'duration' (seconds)"));
242	      cJSON_AddBoolToObject(result, "isError", true);
243	      return resp;
244	    }
245	
246	  int duration = dur_item->valueint;
247	  if (duration <= 0 || duration > 86400)  /* max 24 hours */
248	    {
249	      cJSON *resp   = reply_result(id);
250	      cJSON *result = cJSON_GetObjectItem(resp, "result");
251	      cJSON_AddItemToObject(result, "content",
252	        make_text_content("Duration must be between 1 and 86400 seconds"));
253	      cJSON_AddBoolToObject(result, "isError", true);
254	      return resp;
255	    }
256	
257	  struct timer_s *t = timer_alloc();
258	  if (t == NULL)
259	    {
260	      cJSON *resp   = reply_result(id);
261	      cJSON *result = cJSON_GetObjectItem(resp, "result");
262	      cJSON_AddItemToObject(result, "content",
263	        make_text_content("Too many active timers (max 8)"));
264	      cJSON_AddBoolToObject(result, "isError", true);
265	      return resp;
266	    }
267	
268	  t->end_time = time(NULL) + duration;
269	
270	  cJSON *msg_item = cJSON_GetObjectItem(args, "message");
271	  if (cJSON_IsString(msg_item))
272	    {
273	      strncpy(t->message, msg_item->valuestring,
274	              TIMER_MSG_MAX - 1);
275	      t->message[TIMER_MSG_MAX - 1] = '\0';
276	    }
277	  else
278	    {
279	      snprintf(t->message, sizeof(t->message), "Timer %d", t->id);
280	    }
281	
282	  fprintf(stderr, "[mcp_server] timer %d set: %d seconds, msg=\"%s\"\n",
283	          t->id, duration, t->message);
284	
285	  /* Build success response with timer info. */
286	
287	  {
288	    char text[256];
289	    cJSON *resp   = reply_result(id);
290	    cJSON *result = cJSON_GetObjectItem(resp, "result");
291	
292	    snprintf(text, sizeof(text),
293	             "Timer %d 已设置，%d 秒后到期。消息: %s",
294	             t->id, duration, t->message);
295	    cJSON_AddItemToObject(result, "content", make_text_content(text));
296	    cJSON_AddBoolToObject(result, "isError", false);
297	    return resp;
298	  }
299	}
300	
301	/* Handle "cancel_timer" tool call.
302	 *   arguments:
303	 *     timer_id  (int, required) — id of the timer to cancel
304	 */
305	
306	static cJSON *handle_cancel_timer(cJSON *id, cJSON *params)
307	{
308	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
309	  if (args == NULL)
310	    {
311	      cJSON *resp   = reply_result(id);
312	      cJSON *result = cJSON_GetObjectItem(resp, "result");
313	      cJSON_AddItemToObject(result, "content",
314	        make_text_content("Missing arguments"));
315	      cJSON_AddBoolToObject(result, "isError", true);
316	      return resp;
317	    }
318	
319	  cJSON *tid_item = cJSON_GetObjectItem(args, "timer_id");
320	  if (!cJSON_IsNumber(tid_item))
321	    {
322	      cJSON *resp   = reply_result(id);
323	      cJSON *result = cJSON_GetObjectItem(resp, "result");
324	      cJSON_AddItemToObject(result, "content",
325	        make_text_content("Missing or invalid 'timer_id'"));
326	      cJSON_AddBoolToObject(result, "isError", true);
327	      return resp;
328	    }
329	
330	  int timer_id = tid_item->valueint;
331	  struct timer_s *t = timer_find(timer_id);
332	  if (t == NULL)
333	    {
334	      char msg[64];
335	      cJSON *resp;
336	      cJSON *result;
337	      snprintf(msg, sizeof(msg), "Timer %d not found", timer_id);
338	      resp   = reply_result(id);
339	      result = cJSON_GetObjectItem(resp, "result");
340	      cJSON_AddItemToObject(result, "content", make_text_content(msg));
341	      cJSON_AddBoolToObject(result, "isError", true);
342	      return resp;
343	    }
344	
345	  timer_cancel(t);
346	  fprintf(stderr, "[mcp_server] timer %d cancelled\n", timer_id);
347	
348	  {
349	    char text[128];
350	    cJSON *resp   = reply_result(id);
351	    cJSON *result = cJSON_GetObjectItem(resp, "result");
352	    snprintf(text, sizeof(text), "Timer %d 已取消", timer_id);
353	    cJSON_AddItemToObject(result, "content", make_text_content(text));
354	    cJSON_AddBoolToObject(result, "isError", false);
355	    return resp;
356	  }
357	}
