359	/* Handle "list_timers" tool call. No arguments required. */
360	
361	static cJSON *handle_list_timers(cJSON *id)
362	{
363	  cJSON *resp   = reply_result(id);
364	  cJSON *result = cJSON_GetObjectItem(resp, "result");
365	  cJSON *content = cJSON_CreateArray();
366	  time_t now = time(NULL);
367	  int count = 0;
368	
369	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
370	    {
371	      if (g_timers[i].active)
372	        {
373	          char text[256];
374	          int remaining = (int)(g_timers[i].end_time - now);
375	          if (remaining < 0)
376	            {
377	              remaining = 0;
378	            }
379	
380	          snprintf(text, sizeof(text),
381	                   "Timer %d: 还剩 %d 秒, 消息: \"%s\"",
382	                   g_timers[i].id, remaining, g_timers[i].message);
383	
384	          cJSON *item = cJSON_CreateObject();
385	          cJSON_AddStringToObject(item, "type", "text");
386	          cJSON_AddStringToObject(item, "text", text);
387	          cJSON_AddItemToArray(content, item);
388	          count++;
389	        }
390	    }
391	
392	  if (count == 0)
393	    {
394	      cJSON *item = cJSON_CreateObject();
395	      cJSON_AddStringToObject(item, "type", "text");
396	      cJSON_AddStringToObject(item, "text", "当前没有活动的计时器");
397	      cJSON_AddItemToArray(content, item);
398	    }
399	
400	  cJSON_AddItemToObject(result, "content", content);
401	  cJSON_AddBoolToObject(result, "isError", false);
402	  return resp;
403	}
