543	/* tools/call: dispatch by name. */
544	static cJSON *handle_tools_call(cJSON *id, cJSON *params)
545	{
546	  cJSON *name = cJSON_GetObjectItem(params, "name");
547	  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;
548	
549	  if (namestr == NULL)
550	    {
551	      return reply_error(id, -32602, "Missing tool name");
552	    }
553	
554	  /* Dispatch to the appropriate handler. */
555	
556	  if (strcmp(namestr, "start_app") == 0)
557	    {
558	      cJSON *args     = cJSON_GetObjectItem(params, "arguments");
559	      cJSON *appname = (args != NULL) ?
560	        cJSON_GetObjectItem(args, "app_name") : NULL;
561	      const char *appstr = cJSON_IsString(appname) ?
562	        appname->valuestring : NULL;
563	
564	      if (appstr == NULL)
565	        {
566	          cJSON *resp     = reply_result(id);
567	          cJSON *result   = cJSON_GetObjectItem(resp, "result");
568	          cJSON_AddItemToObject(result, "content",
569	            make_text_content("Missing app_name argument"));
570	          cJSON_AddBoolToObject(result, "isError", true);
571	          return resp;
572	        }
573	
574	      const struct app_entry_s *app = find_app(appstr);
575	      if (app == NULL)
576	        {
577	          char msg[64];
578	          cJSON *resp;
579	          cJSON *result;
580	          snprintf(msg, sizeof(msg), "Unknown application: %s", appstr);
581	          resp   = reply_result(id);
582	          result = cJSON_GetObjectItem(resp, "result");
583	          cJSON_AddItemToObject(result, "content", make_text_content(msg));
584	          cJSON_AddBoolToObject(result, "isError", true);
585	          return resp;
586	        }
587	
588	      /* Launch the builtin application. argv[0] is the program name. */
589	      {
590	        char *argv[2] = { (char *)app->prog, NULL };
591	        pid_t pid;
592	        int ret = posix_spawn(&pid, app->prog, NULL, NULL, argv, NULL);
593	        if (ret != 0)
594	          {
595	            char msg[64];
596	            cJSON *resp;
597	            cJSON *result;
598	            snprintf(msg, sizeof(msg), "Failed to launch %s: %d", appstr, ret);
599	            resp   = reply_result(id);
600	            result = cJSON_GetObjectItem(resp, "result");
601	            cJSON_AddItemToObject(result, "content", make_text_content(msg));
602	            cJSON_AddBoolToObject(result, "isError", true);
603	            return resp;
604	          }
605	
606	        /* Don't wait — let the launched app run independently. */
607	        {
608	          char msg[64];
609	          cJSON *resp;
610	          cJSON *result;
611	          snprintf(msg, sizeof(msg), "已启动应用 %s", appstr);
612	          resp   = reply_result(id);
613	          result = cJSON_GetObjectItem(resp, "result");
614	          cJSON_AddItemToObject(result, "content", make_text_content(msg));
615	          cJSON_AddBoolToObject(result, "isError", false);
616	          return resp;
617	        }
618	      }
619	    }
620	
621	  if (strcmp(namestr, "set_timer") == 0)
622	    {
623	      return handle_set_timer(id, params);
624	    }
625	
626	  if (strcmp(namestr, "cancel_timer") == 0)
627	    {
628	      return handle_cancel_timer(id, params);
629	    }
630	
631	  if (strcmp(namestr, "list_timers") == 0)
632	    {
633	      return handle_list_timers(id);
634	    }
635	
636	  return reply_error(id, -32601, "Unknown tool");
637	}
638	
639	/* Dispatch one JSON-RPC request object to a handler and return the response. */
640	static cJSON *dispatch(cJSON *req)
641	{
642	  cJSON *method = cJSON_GetObjectItem(req, "method");
643	  cJSON *id     = cJSON_GetObjectItem(req, "id");
644	  cJSON *params = cJSON_GetObjectItem(req, "params");
645	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
646	
647	  if (mstr == NULL)
648	    {
649	      return reply_error(id, -32600, "Missing method");
650	    }
651	
652	  if (strcmp(mstr, "initialize") == 0)
653	    {
654	      return handle_initialize(id);
655	    }
656	
657	  if (strcmp(mstr, "tools/list") == 0)
658	    {
659	      return handle_tools_list(id);
660	    }
661	
662	  if (strcmp(mstr, "tools/call") == 0)
663	    {
664	      return handle_tools_call(id, params ? params : cJSON_CreateObject());
665	    }
666	
667	  /* Notifications (no id) are not answered. */
668	  if (id == NULL)
669	    {
670	      return NULL;
671	    }
672	
673	  {
674	    char msg[80];
675	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
676	    return reply_error(id, -32601, msg);
677	  }
678	}
