683	
684	int main(int argc, FAR char *argv[])
685	{
686	  char line[MCP_LINE_MAX];
687	  time_t last_check = time(NULL);
688	
689	  fprintf(stderr, "[mcp_server] started (stdio transport)\n");
690	
691	  /* Set stdin to non-blocking mode for polling. */
692	
693	  int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
694	  if (flags >= 0)
695	    {
696	      fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);
697	    }
698	
699	  /* Main loop: poll stdin for requests and check timer expirations. */
700	
701	  while (true)
702	    {
703	      /* Check for expired timers every second. */
704	
705	      time_t now = time(NULL);
706	      if (now > last_check)
707	        {
708	          for (int i = 0; i < TIMER_MAX_COUNT; i++)
709	            {
710	              if (g_timers[i].active && now >= g_timers[i].end_time)
711	                {
712	                  fprintf(stderr,
713	                          "[mcp_server] TIMER %d EXPIRED: \"%s\"\n",
714	                          g_timers[i].id, g_timers[i].message);
715	                  g_timers[i].active = false;
716	                }
717	            }
718	
719	          last_check = now;
720	        }
721	
722	      /* Try to read a line from stdin (non-blocking). */
723	
724	      ssize_t n = read(STDIN_FILENO, line, sizeof(line) - 1);
725	      if (n <= 0)
726	        {
727	          /* No data available or EOF. Sleep briefly and retry. */
728	
729	          usleep(100000);  /* 100ms */
730	          continue;
731	        }
732	
733	      /* Handle partial reads (line not yet complete). */
734	
735	      if (line[n - 1] != '\n')
736	        {
737	          /* Keep reading until we get a newline. */
738	
739	          size_t total = n;
740	          while (total < sizeof(line) - 1)
741	            {
742	              ssize_t more = read(STDIN_FILENO, line + total,
743	                                  sizeof(line) - 1 - total);
744	              if (more <= 0)
745	                {
746	                  break;
747	                }
748	
749	              total += more;
750	              if (line[total - 1] == '\n')
751	                {
752	                  break;
753	                }
754	            }
755	
756	          n = total;
757	        }
758	
759	      /* Strip trailing newline. */
760	
761	      size_t len = n;
762	      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
763	        {
764	          line[--len] = '\0';
765	        }
766	
767	      if (len == 0)
768	        {
769	          continue;
770	        }
771	
772	      cJSON *req = cJSON_Parse(line);
773	      if (req == NULL)
774	        {
775	          cJSON *resp = reply_error(NULL, -32700, "Parse error");
776	          send_response(resp);
777	          continue;
778	        }
779	
780	      cJSON *resp = dispatch(req);
781	      cJSON_Delete(req);
782	
783	      if (resp != NULL)
784	        {
785	          send_response(resp);
786	        }
787	    }
788	
789	  fprintf(stderr, "[mcp_server] exiting\n");
790	  return 0;
791	}
