223	/*
224	 * 初始化UI系统。
225	 * 创建IPC端点，用于接收和处理UI数据。
226	 *
227	 * @return 0 表示成功，-1 表示创建IPC端点失败
228	 */
229	int ui_system_init(void)
230	{
231	    // 创建UDP IPC端点
232	    g_ipc_ep = ipc_endpoint_create_udp(UI_PORT_DOWN, UI_PORT_UP, process_ui_data, NULL);
233	    if (!g_ipc_ep) {
234	        LV_LOG_ERROR("Failed to create IPC endpoint\n");
235	        return -1;
236	    }
237	
238	    lv_timer_create(apply_pending_ui_update, 50, NULL);
239	    return 0;
240	}
