114	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
115	 * equivalents so the limited CJK font (basic ideographs only) can render
116	 * all visible characters without falling back to [][].
117	 */
118	static void sanitize_text(char *dst, size_t dstsize, const char *src)
119	{
120	  size_t di = 0;
121	  const unsigned char *s = (const unsigned char *)src;
122	
123	  while (*s && di < dstsize - 1)
124	    {
125	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
126	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
127	          s[2] >= 0x80 && s[2] < 0xc0)
128	        {
129	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
130	                            ((unsigned int)(s[1] & 0x3f) << 6) |
131	                            ((unsigned int)(s[2] & 0x3f));
132	          const char *r = NULL;
133	
134	          switch (cp)
135	            {
136	              case 0xff0c: r = ",";  break;  /* ， */
137	              case 0x3002: r = ".";  break;  /* 。 */
138	              case 0xff01: r = "!";  break;  /* ！ */
139	              case 0xff1f: r = "?";  break;  /* ？ */
140	              case 0xff1a: r = ":";  break;  /* ： */
141	              case 0xff1b: r = ";";  break;  /* ； */
142	              case 0x3001: r = ",";  break;  /* 、 */
143	              case 0x201c: r = "\""; break;  /* " */
144	              case 0x201d: r = "\""; break;  /* " */
145	              case 0x2018: r = "'";  break;  /* ' */
146	              case 0x2019: r = "'";  break;  /* ' */
147	              case 0xff08: r = "(";  break;  /* （ */
148	              case 0xff09: r = ")";  break;  /* ） */
149	              case 0x300a: r = "<<"; break;  /* 《 */
150	              case 0x300b: r = ">>"; break;  /* 》 */
151	              case 0x2026: r = "..."; break; /* … */
152	              case 0x2014: r = "--"; break;  /* — */
153	              default:
154	                {
155	                  /* Keep the original character if it's in CJK range */
156	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
157	                    {
158	                      dst[di++] = s[0];
159	                      dst[di++] = s[1];
160	                      dst[di++] = s[2];
161	                    }
162	                  else
163	                    {
164	                      /* Unknown char: skip */
165	                    }
166	                  s += 3;
167	                  continue;
168	                }
169	            }
170	
171	          /* Write replacement string */
172	          while (*r && di < dstsize - 1)
173	            {
174	              dst[di++] = *r++;
175	            }
176	
177	          s += 3;
178	        }
179	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
180	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
181	        {
182	          s += 2;
183	        }
184	      /* ASCII */
185	      else if (s[0] < 0x80)
186	        {
187	          dst[di++] = *s++;
188	        }
189	      else
190	        {
191	          /* Invalid UTF-8 byte, skip */
192	          s++;
193	        }
194	    }
195	
196	  dst[di] = '\0';
197	}
