1	/****************************************************************************
2	 * apps/examples/mcp_server/mcp_server_main.c
3	 *
4	 * A local MCP (Model Context Protocol) server speaking the stdio transport.
5	 * It exposes tools including:
6	 *   - "start_app": launch a built-in NuttX application via posix_spawn()
7	 *   - "set_timer":  set a countdown timer with optional message
8	 *   - "cancel_timer": cancel an active timer by id
9	 *   - "list_timers": list all active timers
10	 *
11	 * Transport (per the MCP stdio spec): messages are newline-delimited JSON-RPC
12	 * 2.0 objects — one request per line on stdin, one response per line on
13	 * stdout, no embedded newlines. stderr is used for logging only.
14	 *
15	 * This process is spawned by the xiaozhi_voice app, which acts as the MCP
16	 * client and forwards the cloud's MCP requests to this server over its
17	 * stdin/stdout pipes.
18	 *
19	 * SPDX-License-Identifier: Apache-2.0
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <stdio.h>
25	#include <stdlib.h>
26	#include <string.h>
27	#include <stdbool.h>
28	#include <spawn.h>
29	#include <sys/wait.h>
30	#include <errno.h>
31	#include <time.h>
32	#include <signal.h>
33	#include <unistd.h>
34	#include <fcntl.h>
35	
36	#include <netutils/cJSON.h>
37	
38	/****************************************************************************
39	 * Pre-processor Definitions
40	 ****************************************************************************/
41	
42	#define MCP_PROTOCOL_VERSION "2024-11-05"
43	#define MCP_SERVER_NAME       "mcp-server"
44	#define MCP_SERVER_VERSION    "1.0"
45	
46	#define MCP_LINE_MAX  2048
47	
48	/* The fixed list of applications that can be launched. Each entry maps a
49	 * stable, human-friendly name to the NuttX builtin program name passed to
50	 * posix_spawn(). Extend this table to expose more apps.
51	 */
52	struct app_entry_s
53	{
54	  const char *name;   /* name exposed to the LLM via tools/list enum      */
55	  const char *prog;   /* builtin program name passed to posix_spawn()    */
56	};
57	
58	static const struct app_entry_s g_apps[] =
59	{
60	  { "hello", "hello" },
61	};
62	
63	#define APP_COUNT (sizeof(g_apps) / sizeof(g_apps[0]))
64	
65	/* Timer definitions. */
66	
67	#define TIMER_MAX_COUNT  8    /* maximum number of concurrent timers */
68	#define TIMER_MSG_MAX   128   /* maximum length of a timer message */
69	
70	struct timer_s
71	{
72	  bool    active;              /* slot in use */
73	  int     id;                  /* unique timer id (1-based) */
74	  time_t  end_time;            /* absolute expiration time (epoch seconds) */
75	  char    message[TIMER_MSG_MAX]; /* user message (displayed on expiry) */
76	};
77	
78	static struct timer_s g_timers[TIMER_MAX_COUNT];
79	static int g_next_timer_id = 1;
80	
81	/****************************************************************************
82	 * Private Function Prototypes
83	 ****************************************************************************/
84	
85	static cJSON *reply_result(cJSON *id);
86	static cJSON *reply_error(cJSON *id, int code, const char *message);
87	static void send_response(cJSON *resp);
88	static cJSON *handle_initialize(cJSON *id);
89	static cJSON *handle_tools_list(cJSON *id);
90	static cJSON *handle_tools_call(cJSON *id, cJSON *params);
91	static const struct app_entry_s *find_app(const char *name);
92	
93	/* Timer helper functions. */
94	
95	static struct timer_s *timer_alloc(void);
96	static struct timer_s *timer_find(int id);
97	static void timer_cancel(struct timer_s *t);
98	static cJSON *handle_set_timer(cJSON *id, cJSON *params);
99	static cJSON *handle_cancel_timer(cJSON *id, cJSON *params);
100	static cJSON *handle_list_timers(cJSON *id);
101	
102	/****************************************************************************
103	 * Private Functions
104	 ****************************************************************************/
105	
106	/* Build a JSON-RPC result object for the given request id. */
107	static cJSON *reply_result(cJSON *id)
108	{
109	  cJSON *resp = cJSON_CreateObject();
110	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
111	  cJSON_AddItemReferenceToObject(resp, "id", id);
112	  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
113	  return resp;
114	}
115	
116	/* Build a JSON-RPC error object for the given request id and code/message. */
117	static cJSON *reply_error(cJSON *id, int code, const char *message)
118	{
119	  cJSON *resp = cJSON_CreateObject();
120	  cJSON *err  = cJSON_CreateObject();
121	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
122	  cJSON_AddItemReferenceToObject(resp, "id", id);
123	  cJSON_AddItemToObject(resp, "error", err);
124	  cJSON_AddNumberToObject(err, "code", code);
125	  cJSON_AddStringToObject(err, "message", message);
126	  return resp;
127	}
128	
129	/* Serialize a JSON-RPC response as one line on stdout (newline-delimited). */
130	static void send_response(cJSON *resp)
131	{
132	  char *json = cJSON_PrintUnformatted(resp);
133	  if (json != NULL)
134	    {
135	      printf("%s\n", json);
136	      fflush(stdout);
137	      free(json);
138	    }
139	
140	  cJSON_Delete(resp);
141	}
142	
143	/* Build a single text content block (the shape tools/call results use). */
144	static cJSON *make_text_content(const char *text)
145	{
146	  cJSON *content = cJSON_CreateArray();
147	  cJSON *item    = cJSON_CreateObject();
148	  cJSON_AddItemToArray(content, item);
149	  cJSON_AddStringToObject(item, "type", "text");
150	  cJSON_AddStringToObject(item, "text", text);
151	  return content;
152	}
153	
154	static const struct app_entry_s *find_app(const char *name)
155	{
156	  for (size_t i = 0; i < APP_COUNT; i++)
157	    {
158	      if (strcmp(g_apps[i].name, name) == 0)
159	        {
160	          return &g_apps[i];
161	        }
162	    }
163	
164	  return NULL;
165	}
166	
167	/****************************************************************************
168	 * Timer Functions
169	 ****************************************************************************/
170	
171	/* Allocate a new timer slot. Returns NULL if no slot available. */
172	
173	static struct timer_s *timer_alloc(void)
174	{
175	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
176	    {
177	      if (!g_timers[i].active)
178	        {
179	          g_timers[i].active = true;
180	          g_timers[i].id = g_next_timer_id++;
181	          g_timers[i].end_time = 0;
182	          g_timers[i].message[0] = '\0';
183	          return &g_timers[i];
184	        }
185	    }
186	
187	  return NULL;
188	}
189	
190	/* Find a timer by id. Returns NULL if not found. */
191	
192	static struct timer_s *timer_find(int id)
193	{
194	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
195	    {
196	      if (g_timers[i].active && g_timers[i].id == id)
197	        {
198	          return &g_timers[i];
199	        }
200	    }
201	
202	  return NULL;
203	}
204	
205	/* Cancel (deactivate) a timer. */
206	
207	static void timer_cancel(struct timer_s *t)
208	{
209	  if (t != NULL)
210	    {
211	      t->active = false;
212	    }
213	}
214	
215	/* Handle "set_timer" tool call.
216	 *   arguments:
217	 *     duration  (int, required) — seconds from now
218	 *     message   (string, optional) — message to display when timer expires
219	 *   Returns the timer id and remaining seconds.
220	 */
221	
222	static cJSON *handle_set_timer(cJSON *id, cJSON *params)
223	{
224	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
225	  if (args == NULL)
226	    {
227	      cJSON *resp   = reply_result(id);
228	      cJSON *result = cJSON_GetObjectItem(resp, "result");
229	      cJSON_AddItemToObject(result, "content",
230	        make_text_content("Missing arguments"));
231	      cJSON_AddBoolToObject(result, "isError", true);
232	      return resp;
233	    }
234	
235	  cJSON *dur_item = cJSON_GetObjectItem(args, "duration");
236	  if (!cJSON_IsNumber(dur_item))
237	    {
238	      cJSON *resp   = reply_result(id);
239	      cJSON *result = cJSON_GetObjectItem(resp, "result");
240	      cJSON_AddItemToObject(result, "content",
241	        make_text_content("Missing or invalid 'duration' (seconds)"));
242	      cJSON_AddBoolToObject(result, "isError", true);
243	      return resp;
244	    }
245	
246	  int duration = dur_item->valueint;
247	  if (duration <= 0 || duration > 86400)  /* max 24 hours */
248	    {
249	      cJSON *resp   = reply_result(id);
250	      cJSON *result = cJSON_GetObjectItem(resp, "result");
251	      cJSON_AddItemToObject(result, "content",
252	        make_text_content("Duration must be between 1 and 86400 seconds"));
253	      cJSON_AddBoolToObject(result, "isError", true);
254	      return resp;
255	    }
256	
257	  struct timer_s *t = timer_alloc();
258	  if (t == NULL)
259	    {
260	      cJSON *resp   = reply_result(id);
261	      cJSON *result = cJSON_GetObjectItem(resp, "result");
262	      cJSON_AddItemToObject(result, "content",
263	        make_text_content("Too many active timers (max 8)"));
264	      cJSON_AddBoolToObject(result, "isError", true);
265	      return resp;
266	    }
267	
268	  t->end_time = time(NULL) + duration;
269	
270	  cJSON *msg_item = cJSON_GetObjectItem(args, "message");
271	  if (cJSON_IsString(msg_item))
272	    {
273	      strncpy(t->message, msg_item->valuestring,
274	              TIMER_MSG_MAX - 1);
275	      t->message[TIMER_MSG_MAX - 1] = '\0';
276	    }
277	  else
278	    {
279	      snprintf(t->message, sizeof(t->message), "Timer %d", t->id);
280	    }
281	
282	  fprintf(stderr, "[mcp_server] timer %d set: %d seconds, msg=\"%s\"\n",
283	          t->id, duration, t->message);
284	
285	  /* Build success response with timer info. */
286	
287	  {
288	    char text[256];
289	    cJSON *resp   = reply_result(id);
290	    cJSON *result = cJSON_GetObjectItem(resp, "result");
291	
292	    snprintf(text, sizeof(text),
293	             "Timer %d 已设置，%d 秒后到期。消息: %s",
294	             t->id, duration, t->message);
295	    cJSON_AddItemToObject(result, "content", make_text_content(text));
296	    cJSON_AddBoolToObject(result, "isError", false);
297	    return resp;
298	  }
299	}
300	
301	/* Handle "cancel_timer" tool call.
302	 *   arguments:
303	 *     timer_id  (int, required) — id of the timer to cancel
304	 */
305	
306	static cJSON *handle_cancel_timer(cJSON *id, cJSON *params)
307	{
308	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
309	  if (args == NULL)
310	    {
311	      cJSON *resp   = reply_result(id);
312	      cJSON *result = cJSON_GetObjectItem(resp, "result");
313	      cJSON_AddItemToObject(result, "content",
314	        make_text_content("Missing arguments"));
315	      cJSON_AddBoolToObject(result, "isError", true);
316	      return resp;
317	    }
318	
319	  cJSON *tid_item = cJSON_GetObjectItem(args, "timer_id");
320	  if (!cJSON_IsNumber(tid_item))
321	    {
322	      cJSON *resp   = reply_result(id);
323	      cJSON *result = cJSON_GetObjectItem(resp, "result");
324	      cJSON_AddItemToObject(result, "content",
325	        make_text_content("Missing or invalid 'timer_id'"));
326	      cJSON_AddBoolToObject(result, "isError", true);
327	      return resp;
328	    }
329	
330	  int timer_id = tid_item->valueint;
331	  struct timer_s *t = timer_find(timer_id);
332	  if (t == NULL)
333	    {
334	      char msg[64];
335	      cJSON *resp;
336	      cJSON *result;
337	      snprintf(msg, sizeof(msg), "Timer %d not found", timer_id);
338	      resp   = reply_result(id);
339	      result = cJSON_GetObjectItem(resp, "result");
340	      cJSON_AddItemToObject(result, "content", make_text_content(msg));
341	      cJSON_AddBoolToObject(result, "isError", true);
342	      return resp;
343	    }
344	
345	  timer_cancel(t);
346	  fprintf(stderr, "[mcp_server] timer %d cancelled\n", timer_id);
347	
348	  {
349	    char text[128];
350	    cJSON *resp   = reply_result(id);
351	    cJSON *result = cJSON_GetObjectItem(resp, "result");
352	    snprintf(text, sizeof(text), "Timer %d 已取消", timer_id);
353	    cJSON_AddItemToObject(result, "content", make_text_content(text));
354	    cJSON_AddBoolToObject(result, "isError", false);
355	    return resp;
356	  }
357	}
358	
359	/* Handle "list_timers" tool call. No arguments required. */
360	
361	static cJSON *handle_list_timers(cJSON *id)
362	{
363	  cJSON *resp   = reply_result(id);
364	  cJSON *result = cJSON_GetObjectItem(resp, "result");
365	  cJSON *content = cJSON_CreateArray();
366	  time_t now = time(NULL);
367	  int count = 0;
368	
369	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
370	    {
371	      if (g_timers[i].active)
372	        {
373	          char text[256];
374	          int remaining = (int)(g_timers[i].end_time - now);
375	          if (remaining < 0)
376	            {
377	              remaining = 0;
378	            }
379	
380	          snprintf(text, sizeof(text),
381	                   "Timer %d: 还剩 %d 秒, 消息: \"%s\"",
382	                   g_timers[i].id, remaining, g_timers[i].message);
383	
384	          cJSON *item = cJSON_CreateObject();
385	          cJSON_AddStringToObject(item, "type", "text");
386	          cJSON_AddStringToObject(item, "text", text);
387	          cJSON_AddItemToArray(content, item);
388	          count++;
389	        }
390	    }
391	
392	  if (count == 0)
393	    {
394	      cJSON *item = cJSON_CreateObject();
395	      cJSON_AddStringToObject(item, "type", "text");
396	      cJSON_AddStringToObject(item, "text", "当前没有活动的计时器");
397	      cJSON_AddItemToArray(content, item);
398	    }
399	
400	  cJSON_AddItemToObject(result, "content", content);
401	  cJSON_AddBoolToObject(result, "isError", false);
402	  return resp;
403	}
