405	/* initialize: report server info, protocol version, and capabilities. */
406	static cJSON *handle_initialize(cJSON *id)
407	{
408	  cJSON *resp     = reply_result(id);
409	  cJSON *result   = cJSON_GetObjectItem(resp, "result");
