639	/* Dispatch one JSON-RPC request object to a handler and return the response. */
640	static cJSON *dispatch(cJSON *req)
641	{
642	  cJSON *method = cJSON_GetObjectItem(req, "method");
643	  cJSON *id     = cJSON_GetObjectItem(req, "id");
644	  cJSON *params = cJSON_GetObjectItem(req, "params");
645	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
646	
647	  if (mstr == NULL)
648	    {
649	      return reply_error(id, -32600, "Missing method");
650	    }
651	
652	  if (strcmp(mstr, "initialize") == 0)
653	    {
654	      return handle_initialize(id);
655	    }
656	
657	  if (strcmp(mstr, "tools/list") == 0)
658	    {
659	      return handle_tools_list(id);
660	    }
661	
662	  if (strcmp(mstr, "tools/call") == 0)
663	    {
664	      return handle_tools_call(id, params ? params : cJSON_CreateObject());
665	    }
666	
667	  /* Notifications (no id) are not answered. */
668	  if (id == NULL)
669	    {
670	      return NULL;
671	    }
672	
673	  {
674	    char msg[80];
675	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
676	    return reply_error(id, -32601, msg);
677	  }
678	}
