/****************************************************************************
 * apps/examples/tswatch/xiaozhi_voice/mcp_server.c
 *
 * In-process MCP (Model Context Protocol) server for the tswatch build.
 * Handles JSON-RPC 2.0 requests directly (no subprocess, no stdio).
 * Exposes timer tools: set_timer, cancel_timer, list_timers.
 *
 * Adapted from the openvela mcp_server_main.c subprocess-based server.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>
#include <time.h>

#include <netutils/cJSON.h>

#include "mcp_server.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MCP_PROTOCOL_VERSION "2024-11-05"
#define MCP_SERVER_NAME       "mcp-server"
#define MCP_SERVER_VERSION    "1.0"

/* Timer definitions. */

#define TIMER_MAX_COUNT  8    /* maximum number of concurrent timers */
#define TIMER_MSG_MAX   128   /* maximum length of a timer message */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct timer_s
{
  bool    active;              /* slot in use */
  int     id;                  /* unique timer id (1-based) */
  time_t  end_time;            /* absolute expiration time (epoch seconds) */
  char    message[TIMER_MSG_MAX]; /* user message (displayed on expiry) */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct timer_s g_timers[TIMER_MAX_COUNT];
static int g_next_timer_id = 1;

/* Most recently expired timer message (valid until next check_timers). */

static char g_last_expired_msg[TIMER_MSG_MAX];
static int  g_expired_count;

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static cJSON *reply_result(cJSON *id);
static cJSON *reply_error(cJSON *id, int code, const char *message);
static cJSON *handle_initialize(cJSON *id);
static cJSON *handle_tools_list(cJSON *id);
static cJSON *handle_tools_call(cJSON *id, cJSON *params);

/* Timer helper functions. */

static struct timer_s *timer_alloc(void);
static struct timer_s *timer_find(int id);
static void timer_cancel(struct timer_s *t);
static cJSON *handle_set_timer(cJSON *id, cJSON *params);
static cJSON *handle_cancel_timer(cJSON *id, cJSON *params);
static cJSON *handle_list_timers(cJSON *id);

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Build a JSON-RPC result object for the given request id. */

static cJSON *reply_result(cJSON *id)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
  return resp;
}

/* Build a JSON-RPC error object for the given request id and code/message. */

static cJSON *reply_error(cJSON *id, int code, const char *message)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON *err  = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "error", err);
  cJSON_AddNumberToObject(err, "code", code);
  cJSON_AddStringToObject(err, "message", message);
  return resp;
}

/* Build a single text content block (the shape tools/call results use). */

static cJSON *make_text_content(const char *text)
{
  cJSON *content = cJSON_CreateArray();
  cJSON *item    = cJSON_CreateObject();
  cJSON_AddItemToArray(content, item);
  cJSON_AddStringToObject(item, "type", "text");
  cJSON_AddStringToObject(item, "text", text);
  return content;
}

/****************************************************************************
 * Timer Functions
 ****************************************************************************/

/* Allocate a new timer slot. Returns NULL if no slot available. */

static struct timer_s *timer_alloc(void)
{
  for (int i = 0; i < TIMER_MAX_COUNT; i++)
    {
      if (!g_timers[i].active)
        {
          g_timers[i].active = true;
          g_timers[i].id = g_next_timer_id++;
          g_timers[i].end_time = 0;
          g_timers[i].message[0] = '\0';
          return &g_timers[i];
        }
    }

  return NULL;
}

/* Find a timer by id. Returns NULL if not found. */

static struct timer_s *timer_find(int id)
{
  for (int i = 0; i < TIMER_MAX_COUNT; i++)
    {
      if (g_timers[i].active && g_timers[i].id == id)
        {
          return &g_timers[i];
        }
    }

  return NULL;
}

/* Cancel (deactivate) a timer. */

static void timer_cancel(struct timer_s *t)
{
  if (t != NULL)
    {
      t->active = false;
    }
}

/* Handle "set_timer" tool call.
 *   arguments:
 *     duration  (int, required) — seconds from now
 *     message   (string, optional) — message to display when timer expires
 *   Returns the timer id and remaining seconds.
 */

static cJSON *handle_set_timer(cJSON *id, cJSON *params)
{
  cJSON *args = cJSON_GetObjectItem(params, "arguments");
  if (args == NULL)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing arguments"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  cJSON *dur_item = cJSON_GetObjectItem(args, "duration");
  if (!cJSON_IsNumber(dur_item))
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing or invalid 'duration' (seconds)"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  int duration = dur_item->valueint;
  if (duration <= 0 || duration > 86400)  /* max 24 hours */
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Duration must be between 1 and 86400 seconds"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  struct timer_s *t = timer_alloc();
  if (t == NULL)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Too many active timers (max 8)"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  t->end_time = time(NULL) + duration;

  cJSON *msg_item = cJSON_GetObjectItem(args, "message");
  if (cJSON_IsString(msg_item))
    {
      strncpy(t->message, msg_item->valuestring,
              TIMER_MSG_MAX - 1);
      t->message[TIMER_MSG_MAX - 1] = '\0';
    }
  else
    {
      snprintf(t->message, sizeof(t->message), "Timer %d", t->id);
    }

  printf("[mcp] timer %d set: %d seconds, msg=\"%s\"\n",
         t->id, duration, t->message);

  /* Build success response with timer info. */

  {
    char text[256];
    cJSON *resp   = reply_result(id);
    cJSON *result = cJSON_GetObjectItem(resp, "result");

    snprintf(text, sizeof(text),
             "Timer %d 已设置，%d 秒后到期。消息: %s",
             t->id, duration, t->message);
    cJSON_AddItemToObject(result, "content", make_text_content(text));
    cJSON_AddBoolToObject(result, "isError", false);
    return resp;
  }
}

/* Handle "cancel_timer" tool call.
 *   arguments:
 *     timer_id  (int, required) — id of the timer to cancel
 */

static cJSON *handle_cancel_timer(cJSON *id, cJSON *params)
{
  cJSON *args = cJSON_GetObjectItem(params, "arguments");
  if (args == NULL)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing arguments"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  cJSON *tid_item = cJSON_GetObjectItem(args, "timer_id");
  if (!cJSON_IsNumber(tid_item))
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing or invalid 'timer_id'"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  int timer_id = tid_item->valueint;
  struct timer_s *t = timer_find(timer_id);
  if (t == NULL)
    {
      char msg[64];
      cJSON *resp;
      cJSON *result;
      snprintf(msg, sizeof(msg), "Timer %d not found", timer_id);
      resp   = reply_result(id);
      result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content", make_text_content(msg));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  timer_cancel(t);
  printf("[mcp] timer %d cancelled\n", timer_id);

  {
    char text[128];
    cJSON *resp   = reply_result(id);
    cJSON *result = cJSON_GetObjectItem(resp, "result");
    snprintf(text, sizeof(text), "Timer %d 已取消", timer_id);
    cJSON_AddItemToObject(result, "content", make_text_content(text));
    cJSON_AddBoolToObject(result, "isError", false);
    return resp;
  }
}

/* Handle "list_timers" tool call. No arguments required. */

static cJSON *handle_list_timers(cJSON *id)
{
  cJSON *resp    = reply_result(id);
  cJSON *result  = cJSON_GetObjectItem(resp, "result");
  cJSON *content = cJSON_CreateArray();
  time_t now = time(NULL);
  int count = 0;

  for (int i = 0; i < TIMER_MAX_COUNT; i++)
    {
      if (g_timers[i].active)
        {
          char text[256];
          int remaining = (int)(g_timers[i].end_time - now);
          if (remaining < 0)
            {
              remaining = 0;
            }

          snprintf(text, sizeof(text),
                   "Timer %d: 还剩 %d 秒, 消息: \"%s\"",
                   g_timers[i].id, remaining, g_timers[i].message);

          cJSON *item = cJSON_CreateObject();
          cJSON_AddStringToObject(item, "type", "text");
          cJSON_AddStringToObject(item, "text", text);
          cJSON_AddItemToArray(content, item);
          count++;
        }
    }

  if (count == 0)
    {
      cJSON *item = cJSON_CreateObject();
      cJSON_AddStringToObject(item, "type", "text");
      cJSON_AddStringToObject(item, "text", "当前没有活动的计时器");
      cJSON_AddItemToArray(content, item);
    }

  cJSON_AddItemToObject(result, "content", content);
  cJSON_AddBoolToObject(result, "isError", false);
  return resp;
}

/* initialize: report server info, protocol version, and capabilities. */

static cJSON *handle_initialize(cJSON *id)
{
  cJSON *resp     = reply_result(id);
  cJSON *result   = cJSON_GetObjectItem(resp, "result");
  cJSON *info     = cJSON_CreateObject();
  cJSON *caps     = cJSON_CreateObject();
  cJSON *toolscap = cJSON_CreateObject();

  cJSON_AddStringToObject(result, "protocolVersion", MCP_PROTOCOL_VERSION);
  cJSON_AddItemToObject(result, "serverInfo", info);
  cJSON_AddStringToObject(info, "name", MCP_SERVER_NAME);
  cJSON_AddStringToObject(info, "version", MCP_SERVER_VERSION);
  cJSON_AddItemToObject(result, "capabilities", caps);
  cJSON_AddItemToObject(caps, "tools", toolscap);
  cJSON_AddBoolToObject(toolscap, "listChanged", false);
  return resp;
}

/* tools/list: advertise the timer tools. */

static cJSON *handle_tools_list(cJSON *id)
{
  cJSON *resp   = reply_result(id);
  cJSON *result = cJSON_GetObjectItem(resp, "result");
  cJSON *tools  = cJSON_CreateArray();

  /* --- set_timer tool --- */

  {
    cJSON *tool   = cJSON_CreateObject();
    cJSON *schema = cJSON_CreateObject();
    cJSON *props  = cJSON_CreateObject();
    cJSON *durarg = cJSON_CreateObject();
    cJSON *msgarg = cJSON_CreateObject();
    cJSON *reqd   = cJSON_CreateArray();

    cJSON_AddStringToObject(tool, "name", "set_timer");
    cJSON_AddStringToObject(tool, "description",
      "设置一个倒计时计时器。到期时设备会发出提示音。"
      "例如语音指令\"设置5分钟的计时器\"时调用此工具。");
    cJSON_AddItemToObject(tool, "inputSchema", schema);

    cJSON_AddStringToObject(schema, "type", "object");
    cJSON_AddItemToObject(schema, "properties", props);

    cJSON_AddItemToObject(props, "duration", durarg);
    cJSON_AddStringToObject(durarg, "type", "integer");
    cJSON_AddStringToObject(durarg, "description",
      "计时器持续时间（秒）。例如 300 表示 5 分钟。");

    cJSON_AddItemToObject(props, "message", msgarg);
    cJSON_AddStringToObject(msgarg, "type", "string");
    cJSON_AddStringToObject(msgarg, "description",
      "计时器到期时显示的消息（可选）");

    cJSON_AddItemToObject(schema, "required", reqd);
    cJSON_AddItemToArray(reqd, cJSON_CreateString("duration"));

    cJSON_AddItemToArray(tools, tool);
  }

  /* --- cancel_timer tool --- */

  {
    cJSON *tool   = cJSON_CreateObject();
    cJSON *schema = cJSON_CreateObject();
    cJSON *props  = cJSON_CreateObject();
    cJSON *tidarg = cJSON_CreateObject();
    cJSON *reqd   = cJSON_CreateArray();

    cJSON_AddStringToObject(tool, "name", "cancel_timer");
    cJSON_AddStringToObject(tool, "description",
      "取消一个活动的计时器。例如语音指令\"取消计时器\"时调用此工具。");
    cJSON_AddItemToObject(tool, "inputSchema", schema);

    cJSON_AddStringToObject(schema, "type", "object");
    cJSON_AddItemToObject(schema, "properties", props);

    cJSON_AddItemToObject(props, "timer_id", tidarg);
    cJSON_AddStringToObject(tidarg, "type", "integer");
    cJSON_AddStringToObject(tidarg, "description",
      "要取消的计时器 ID（从 list_timers 获取）");

    cJSON_AddItemToObject(schema, "required", reqd);
    cJSON_AddItemToArray(reqd, cJSON_CreateString("timer_id"));

    cJSON_AddItemToArray(tools, tool);
  }

  /* --- list_timers tool --- */

  {
    cJSON *tool   = cJSON_CreateObject();
    cJSON *schema = cJSON_CreateObject();

    cJSON_AddStringToObject(tool, "name", "list_timers");
    cJSON_AddStringToObject(tool, "description",
      "列出所有活动的计时器及其剩余时间。");
    cJSON_AddItemToObject(tool, "inputSchema", schema);

    cJSON_AddStringToObject(schema, "type", "object");

    cJSON_AddItemToArray(tools, tool);
  }

  cJSON_AddItemToObject(result, "tools", tools);
  return resp;
}

/* tools/call: dispatch by name. */

static cJSON *handle_tools_call(cJSON *id, cJSON *params)
{
  cJSON *name = cJSON_GetObjectItem(params, "name");
  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;

  if (namestr == NULL)
    {
      return reply_error(id, -32602, "Missing tool name");
    }

  if (strcmp(namestr, "set_timer") == 0)
    {
      return handle_set_timer(id, params);
    }

  if (strcmp(namestr, "cancel_timer") == 0)
    {
      return handle_cancel_timer(id, params);
    }

  if (strcmp(namestr, "list_timers") == 0)
    {
      return handle_list_timers(id);
    }

  return reply_error(id, -32601, "Unknown tool");
}

/* Dispatch one JSON-RPC request object to a handler and return the
 * response. Returns NULL for notifications (no id field). */

static cJSON *dispatch(cJSON *req)
{
  cJSON *method = cJSON_GetObjectItem(req, "method");
  cJSON *id     = cJSON_GetObjectItem(req, "id");
  cJSON *params = cJSON_GetObjectItem(req, "params");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      return reply_error(id, -32600, "Missing method");
    }

  if (strcmp(mstr, "initialize") == 0)
    {
      return handle_initialize(id);
    }

  if (strcmp(mstr, "tools/list") == 0)
    {
      return handle_tools_list(id);
    }

  if (strcmp(mstr, "tools/call") == 0)
    {
      return handle_tools_call(id, params ? params : cJSON_CreateObject());
    }

  /* Notifications (no id) are not answered. */

  if (id == NULL)
    {
      return NULL;
    }

  {
    char msg[80];
    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
    return reply_error(id, -32601, msg);
  }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void mcp_server_init(void)
{
  memset(g_timers, 0, sizeof(g_timers));
  g_next_timer_id = 1;
  g_last_expired_msg[0] = '\0';
  g_expired_count = 0;
  printf("[mcp] server initialized\n");
}

cJSON *mcp_server_handle_request(cJSON *request)
{
  if (request == NULL)
    {
      return NULL;
    }

  return dispatch(request);
}

int mcp_server_check_timers(void)
{
  time_t now = time(NULL);
  int expired = 0;

  g_last_expired_msg[0] = '\0';
  g_expired_count = 0;

  for (int i = 0; i < TIMER_MAX_COUNT; i++)
    {
      if (g_timers[i].active && now >= g_timers[i].end_time)
        {
          printf("[mcp] TIMER %d EXPIRED: \"%s\"\n",
                 g_timers[i].id, g_timers[i].message);

          /* Save the last expired message for the caller. */

          strncpy(g_last_expired_msg, g_timers[i].message,
                  TIMER_MSG_MAX - 1);
          g_last_expired_msg[TIMER_MSG_MAX - 1] = '\0';
          g_expired_count++;

          g_timers[i].active = false;
        }
    }

  return g_expired_count;
}

const char *mcp_server_get_last_expired_message(void)
{
  if (g_last_expired_msg[0] == '\0')
    {
      return NULL;
    }

  return g_last_expired_msg;
}

/****************************************************************************
 * apps/examples/tswatch/xiaozhi_voice/xiaozhi_mcp.c
 *
 * MCP (Model Context Protocol) client for the tswatch build.
 * In-process version: calls mcp_server_handle_request() directly instead
 * of spawning a subprocess (no posix_spawn/pipe needed).
 *
 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
 *
 *   { "type": "mcp", "payload": <jsonrpc request> }
 *
 * This module processes the request directly and sends back:
 *
 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#include <netutils/cJSON.h>

#include "xiaozhi_mcp.h"
#include "mcp_server.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Wrap a JSON-RPC response in an "mcp" frame and send it to the cloud. */

static void mcp_send_response(struct xiaozhi_ws_s *ws,
                              const char *session_id,
                              cJSON *resp)
{
  cJSON *frame = cJSON_CreateObject();
  cJSON_AddStringToObject(frame, "type", "mcp");
  cJSON_AddStringToObject(frame, "session_id", session_id);
  cJSON_AddItemToObject(frame, "payload", resp);  /* frame owns resp */

  char *j = cJSON_PrintUnformatted(frame);
  if (j != NULL)
    {
      xiaozhi_ws_send_text(ws, j, strlen(j));
      free(j);
    }

  cJSON_Delete(frame);
}

/* Send a JSON-RPC error response back to the cloud. */

static void mcp_send_error(struct xiaozhi_ws_s *ws,
                           const char *session_id,
                           cJSON *id, int code, const char *message)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON *err  = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  if (id != NULL)
    {
      cJSON_AddItemReferenceToObject(resp, "id", id);
    }

  cJSON_AddItemToObject(resp, "error", err);
  cJSON_AddNumberToObject(err, "code", code);
  cJSON_AddStringToObject(err, "message", message);

  mcp_send_response(ws, session_id, resp);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void xiaozhi_mcp_add_features(cJSON *features)
{
  if (features == NULL)
    {
      return;
    }

  cJSON_AddBoolToObject(features, "mcp", true);
}

void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
                                const char *session_id,
                                cJSON *payload)
{
  cJSON *method = cJSON_GetObjectItem(payload, "method");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      printf("[xiaozhi] mcp: payload has no method\n");
      return;
    }

  printf("[xiaozhi] mcp: handling method=%s\n", mstr);

  /* Process the request directly via the in-process MCP server. */

  cJSON *resp = mcp_server_handle_request(payload);
  if (resp == NULL)
    {
      /* Notification (no id) — nothing to send back. */

      return;
    }

  mcp_send_response(ws, session_id, resp);
}

