/* Timer callback to refresh UI periodically and check MCP timers. */
static void ui_refresh_timer_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);
  ui_refresh(&g_app);

  /* Check for expired MCP timers (once per second via the 100ms timer). */
  {
    static time_t last_timer_check = 0;
    time_t now = time(NULL);
    if (now > last_timer_check)
      {
        int expired = mcp_server_check_timers();
        if (expired > 0)
          {
            const char *msg = mcp_server_get_last_expired_message();
            printf("[xiaozhi] TIMER expired: %s\n",
                   msg ? msg : "(no message)");
          }

        last_timer_check = now;
      }
  }
}

