2	 * apps/examples/tswatch/xiaozhi_voice/mcp_server.c
3	 *
4	 * In-process MCP (Model Context Protocol) server for the tswatch build.
5	 * Handles JSON-RPC 2.0 requests directly (no subprocess, no stdio).
6	 * Exposes timer tools: set_timer, cancel_timer, list_timers.
7	 *
8	 * Adapted from the openvela mcp_server_main.c subprocess-based server.
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
