27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	#define MCP_PROTOCOL_VERSION "2024-11-05"
32	#define MCP_SERVER_NAME       "mcp-server"
33	#define MCP_SERVER_VERSION    "1.0"
34	
35	/* Timer definitions. */
36	
37	#define TIMER_MAX_COUNT  8    /* maximum number of concurrent timers */
38	#define TIMER_MSG_MAX   128   /* maximum length of a timer message */
39	
40	/****************************************************************************
41	 * Private Types
42	 ****************************************************************************/
43	
44	struct timer_s
45	{
46	  bool    active;              /* slot in use */
47	  int     id;                  /* unique timer id (1-based) */
48	  time_t  end_time;            /* absolute expiration time (epoch seconds) */
49	  char    message[TIMER_MSG_MAX]; /* user message (displayed on expiry) */
50	};
51	
52	/* Stopwatch state (single instance). */
53	
54	struct stopwatch_s
55	{
56	  bool     running;            /* true while counting */
57	  uint32_t start_ms;           /* tick when started/resumed (ms) */
58	  uint32_t elapsed_ms;         /* accumulated time when paused (ms) */
59	};
60	
61	/****************************************************************************
62	 * Private Data
63	 ****************************************************************************/
64	
65	static struct timer_s g_timers[TIMER_MAX_COUNT];
66	static int g_next_timer_id = 1;
67	
68	/* Most recently expired timer message (valid until next check_timers). */
69	
70	static char g_last_expired_msg[TIMER_MSG_MAX];
71	static int  g_expired_count;
72	
73	/* Stopwatch state. */
74	
75	static struct stopwatch_s g_stopwatch;
76	
77	/****************************************************************************
78	 * Private Function Prototypes
79	 ****************************************************************************/
80	
81	static cJSON *reply_result(cJSON *id);
82	static cJSON *reply_error(cJSON *id, int code, const char *message);
83	static cJSON *handle_initialize(cJSON *id);
84	static cJSON *handle_tools_list(cJSON *id);
85	static cJSON *handle_tools_call(cJSON *id, cJSON *params);
