103	/****************************************************************************
104	 * Private Functions
105	 ****************************************************************************/
106	
107	/* Build a JSON-RPC result object for the given request id. */
108	
109	static cJSON *reply_result(cJSON *id)
110	{
111	  cJSON *resp = cJSON_CreateObject();
112	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
113	  cJSON_AddItemReferenceToObject(resp, "id", id);
114	  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
115	  return resp;
116	}
117	
118	/* Build a JSON-RPC error object for the given request id and code/message. */
119	
120	static cJSON *reply_error(cJSON *id, int code, const char *message)
121	{
122	  cJSON *resp = cJSON_CreateObject();
123	  cJSON *err  = cJSON_CreateObject();
124	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
125	  cJSON_AddItemReferenceToObject(resp, "id", id);
126	  cJSON_AddItemToObject(resp, "error", err);
127	  cJSON_AddNumberToObject(err, "code", code);
128	  cJSON_AddStringToObject(err, "message", message);
129	  return resp;
130	}
131	
132	/* Build a single text content block (the shape tools/call results use). */
133	
134	static cJSON *make_text_content(const char *text)
135	{
136	  cJSON *content = cJSON_CreateArray();
137	  cJSON *item    = cJSON_CreateObject();
138	  cJSON_AddItemToArray(content, item);
139	  cJSON_AddStringToObject(item, "type", "text");
140	  cJSON_AddStringToObject(item, "text", text);
141	  return content;
142	}
