144	/****************************************************************************
145	 * Timer Functions
146	 ****************************************************************************/
147	
148	/* Allocate a new timer slot. Returns NULL if no slot available. */
149	
150	static struct timer_s *timer_alloc(void)
151	{
152	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
153	    {
154	      if (!g_timers[i].active)
155	        {
156	          g_timers[i].active = true;
157	          g_timers[i].id = g_next_timer_id++;
158	          g_timers[i].end_time = 0;
159	          g_timers[i].message[0] = '\0';
160	          return &g_timers[i];
161	        }
162	    }
163	
164	  return NULL;
165	}
166	
167	/* Find a timer by id. Returns NULL if not found. */
168	
169	static struct timer_s *timer_find(int id)
170	{
171	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
172	    {
173	      if (g_timers[i].active && g_timers[i].id == id)
174	        {
175	          return &g_timers[i];
176	        }
177	    }
178	
179	  return NULL;
180	}
181	
182	/* Cancel (deactivate) a timer. */
183	
184	static void timer_cancel(struct timer_s *t)
185	{
186	  if (t != NULL)
187	    {
188	      t->active = false;
189	    }
190	}
