192	/* Handle "set_timer" tool call.
193	 *   arguments:
194	 *     duration  (int, required) — seconds from now
195	 *     message   (string, optional) — message to display when timer expires
196	 *   Returns the timer id and remaining seconds.
197	 */
198	
199	static cJSON *handle_set_timer(cJSON *id, cJSON *params)
200	{
201	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
202	  if (args == NULL)
203	    {
204	      cJSON *resp   = reply_result(id);
205	      cJSON *result = cJSON_GetObjectItem(resp, "result");
206	      cJSON_AddItemToObject(result, "content",
207	        make_text_content("Missing arguments"));
208	      cJSON_AddBoolToObject(result, "isError", true);
209	      return resp;
210	    }
211	
212	  cJSON *dur_item = cJSON_GetObjectItem(args, "duration");
213	  if (!cJSON_IsNumber(dur_item))
214	    {
215	      cJSON *resp   = reply_result(id);
216	      cJSON *result = cJSON_GetObjectItem(resp, "result");
217	      cJSON_AddItemToObject(result, "content",
218	        make_text_content("Missing or invalid 'duration' (seconds)"));
219	      cJSON_AddBoolToObject(result, "isError", true);
220	      return resp;
221	    }
222	
223	  int duration = dur_item->valueint;
224	  if (duration <= 0 || duration > 86400)  /* max 24 hours */
225	    {
226	      cJSON *resp   = reply_result(id);
227	      cJSON *result = cJSON_GetObjectItem(resp, "result");
228	      cJSON_AddItemToObject(result, "content",
229	        make_text_content("Duration must be between 1 and 86400 seconds"));
230	      cJSON_AddBoolToObject(result, "isError", true);
231	      return resp;
232	    }
233	
234	  struct timer_s *t = timer_alloc();
235	  if (t == NULL)
236	    {
237	      cJSON *resp   = reply_result(id);
238	      cJSON *result = cJSON_GetObjectItem(resp, "result");
239	      cJSON_AddItemToObject(result, "content",
240	        make_text_content("Too many active timers (max 8)"));
241	      cJSON_AddBoolToObject(result, "isError", true);
242	      return resp;
243	    }
244	
245	  t->end_time = time(NULL) + duration;
246	
247	  cJSON *msg_item = cJSON_GetObjectItem(args, "message");
248	  if (cJSON_IsString(msg_item))
249	    {
250	      strncpy(t->message, msg_item->valuestring,
251	              TIMER_MSG_MAX - 1);
252	      t->message[TIMER_MSG_MAX - 1] = '\0';
253	    }
254	  else
255	    {
256	      snprintf(t->message, sizeof(t->message), "Timer %d", t->id);
257	    }
258	
259	  printf("[mcp] timer %d set: %d seconds, msg=\"%s\"\n",
260	         t->id, duration, t->message);
261	
262	  /* Build success response with timer info. */
263	
264	  {
265	    char text[256];
266	    cJSON *resp   = reply_result(id);
267	    cJSON *result = cJSON_GetObjectItem(resp, "result");
268	
269	    snprintf(text, sizeof(text),
270	             "Timer %d 已设置，%d 秒后到期。消息: %s",
271	             t->id, duration, t->message);
272	    cJSON_AddItemToObject(result, "content", make_text_content(text));
273	    cJSON_AddBoolToObject(result, "isError", false);
274	    return resp;
275	  }
276	}
