279	 *   arguments:
280	 *     timer_id  (int, required) — id of the timer to cancel
281	 */
282	
283	static cJSON *handle_cancel_timer(cJSON *id, cJSON *params)
284	{
285	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
286	  if (args == NULL)
287	    {
288	      cJSON *resp   = reply_result(id);
289	      cJSON *result = cJSON_GetObjectItem(resp, "result");
290	      cJSON_AddItemToObject(result, "content",
