299	      cJSON *resp   = reply_result(id);
300	      cJSON *result = cJSON_GetObjectItem(resp, "result");
301	      cJSON_AddItemToObject(result, "content",
302	        make_text_content("Missing or invalid 'timer_id'"));
303	      cJSON_AddBoolToObject(result, "isError", true);
304	      return resp;
305	    }
306	
307	  int timer_id = tid_item->valueint;
308	  struct timer_s *t = timer_find(timer_id);
