382	/****************************************************************************
383	 * Stopwatch Functions
384	 ****************************************************************************/
385	
386	/* Helper: get current elapsed milliseconds. */
387	
388	static uint32_t stopwatch_get_elapsed_ms(void)
389	{
390	  uint32_t now = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
391	  if (g_stopwatch.running)
392	    {
393	      return g_stopwatch.elapsed_ms + (now - g_stopwatch.start_ms);
394	    }
395	
396	  return g_stopwatch.elapsed_ms;
397	}
398	
399	/* Helper: format milliseconds as "MM:SS.mmm". */
400	
401	static void stopwatch_format(uint32_t ms, char *buf, size_t buflen)
402	{
403	  uint32_t minutes = ms / 60000;
404	  uint32_t seconds = (ms % 60000) / 1000;
405	  uint32_t millis  = ms % 1000;
406	  snprintf(buf, buflen, "%02lu:%02lu.%03lu",
407	           (unsigned long)minutes, (unsigned long)seconds,
408	           (unsigned long)millis);
409	}
