411	/* Handle "start_stopwatch" tool call. */
412	
413	static cJSON *handle_start_stopwatch(cJSON *id)
414	{
415	  if (g_stopwatch.running)
416	    {
417	      cJSON *resp   = reply_result(id);
418	      cJSON *result = cJSON_GetObjectItem(resp, "result");
419	      cJSON_AddItemToObject(result, "content",
420	        make_text_content("秒表已经在运行中"));
421	      cJSON_AddBoolToObject(result, "isError", false);
422	      return resp;
423	    }
424	
425	  g_stopwatch.start_ms = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
426	  g_stopwatch.running = true;
427	  printf("[mcp] stopwatch started\n");
428	
429	  {
430	    char text[128];
431	    cJSON *resp   = reply_result(id);
432	    cJSON *result = cJSON_GetObjectItem(resp, "result");
433	    snprintf(text, sizeof(text), "秒表已启动");
434	    cJSON_AddItemToObject(result, "content", make_text_content(text));
435	    cJSON_AddBoolToObject(result, "isError", false);
436	    return resp;
437	  }
438	}
