440	/* Handle "stop_stopwatch" tool call. */
441	
442	static cJSON *handle_stop_stopwatch(cJSON *id)
443	{
444	  if (!g_stopwatch.running)
445	    {
446	      cJSON *resp   = reply_result(id);
447	      cJSON *result = cJSON_GetObjectItem(resp, "result");
448	      cJSON_AddItemToObject(result, "content",
449	        make_text_content("秒表未在运行"));
450	      cJSON_AddBoolToObject(result, "isError", false);
451	      return resp;
452	    }
453	
454	  uint32_t now = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
455	  g_stopwatch.elapsed_ms += (now - g_stopwatch.start_ms);
456	  g_stopwatch.running = false;
457	
458	  {
459	    char time_str[16];
