464	    snprintf(text, sizeof(text), "秒表已停止，当前时间: %s", time_str);
465	    printf("[mcp] stopwatch stopped: %s\n", time_str);
466	    cJSON_AddItemToObject(result, "content", make_text_content(text));
467	    cJSON_AddBoolToObject(result, "isError", false);
468	    return resp;
469	  }
470	}
