699	    }
700	
701	  if (strcmp(namestr, "cancel_timer") == 0)
702	    {
703	      return handle_cancel_timer(id, params);
704	    }
705	
706	  if (strcmp(namestr, "list_timers") == 0)
707	    {
708	      return handle_list_timers(id);
709	    }
710	
711	  if (strcmp(namestr, "start_stopwatch") == 0)
712	    {
713	      return handle_start_stopwatch(id);
