734	/* Dispatch one JSON-RPC request object to a handler and return the
735	 * response. Returns NULL for notifications (no id field). */
736	
737	static cJSON *dispatch(cJSON *req)
738	{
739	  cJSON *method = cJSON_GetObjectItem(req, "method");
740	  cJSON *id     = cJSON_GetObjectItem(req, "id");
741	  cJSON *params = cJSON_GetObjectItem(req, "params");
742	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
743	
744	  if (mstr == NULL)
745	    {
746	      return reply_error(id, -32600, "Missing method");
747	    }
748	
749	  if (strcmp(mstr, "initialize") == 0)
750	    {
751	      return handle_initialize(id);
752	    }
753	
754	  if (strcmp(mstr, "tools/list") == 0)
755	    {
756	      return handle_tools_list(id);
757	    }
758	
759	  if (strcmp(mstr, "tools/call") == 0)
760	    {
761	      return handle_tools_call(id, params ? params : cJSON_CreateObject());
762	    }
763	
764	  /* Notifications (no id) are not answered. */
765	
766	  if (id == NULL)
767	    {
768	      return NULL;
769	    }
770	
771	  {
772	    char msg[80];
773	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
774	    return reply_error(id, -32601, msg);
775	  }
776	}
