804	int mcp_server_check_timers(void)
805	{
806	  time_t now = time(NULL);
807	  int expired = 0;
808	
809	  g_last_expired_msg[0] = '\0';
810	  g_expired_count = 0;
811	
812	  for (int i = 0; i < TIMER_MAX_COUNT; i++)
813	    {
814	      if (g_timers[i].active && now >= g_timers[i].end_time)
815	        {
816	          printf("[mcp] TIMER %d EXPIRED: \"%s\"\n",
817	                 g_timers[i].id, g_timers[i].message);
818	
819	          /* Save the last expired message for the caller. */
820	
821	          strncpy(g_last_expired_msg, g_timers[i].message,
822	                  TIMER_MSG_MAX - 1);
823	          g_last_expired_msg[TIMER_MSG_MAX - 1] = '\0';
824	          g_expired_count++;
825	
826	          g_timers[i].active = false;
827	        }
828	    }
829	
830	  return g_expired_count;
831	}
