118	/* Sanitize UTF-8 text: replace fullwidth CJK punctuation with ASCII
119	 * equivalents so the limited CJK font (basic ideographs only) can render
120	 * all visible characters without falling back to [][].
121	 */
122	static void sanitize_text(char *dst, size_t dstsize, const char *src)
123	{
124	  size_t di = 0;
125	  const unsigned char *s = (const unsigned char *)src;
126	
127	  while (*s && di < dstsize - 1)
128	    {
129	      /* 3-byte UTF-8: U+0800 .. U+FFFF */
130	      if (s[0] >= 0xe0 && s[1] >= 0x80 && s[1] < 0xc0 &&
131	          s[2] >= 0x80 && s[2] < 0xc0)
132	        {
133	          unsigned int cp = ((unsigned int)(s[0] & 0x0f) << 12) |
134	                            ((unsigned int)(s[1] & 0x3f) << 6) |
135	                            ((unsigned int)(s[2] & 0x3f));
136	          const char *r = NULL;
137	
138	          switch (cp)
139	            {
140	              case 0xff0c: r = ",";  break;  /* ， */
141	              case 0x3002: r = ".";  break;  /* 。 */
142	              case 0xff01: r = "!";  break;  /* ！ */
143	              case 0xff1f: r = "?";  break;  /* ？ */
144	              case 0xff1a: r = ":";  break;  /* ： */
145	              case 0xff1b: r = ";";  break;  /* ； */
146	              case 0x3001: r = ",";  break;  /* 、 */
147	              case 0x201c: r = "\""; break;  /* " */
148	              case 0x201d: r = "\""; break;  /* " */
149	              case 0x2018: r = "'";  break;  /* ' */
150	              case 0x2019: r = "'";  break;  /* ' */
151	              case 0xff08: r = "(";  break;  /* （ */
152	              case 0xff09: r = ")";  break;  /* ） */
153	              case 0x300a: r = "<<"; break;  /* 《 */
154	              case 0x300b: r = ">>"; break;  /* 》 */
155	              case 0x2026: r = "..."; break; /* … */
156	              case 0x2014: r = "--"; break;  /* — */
157	              default:
158	                {
159	                  /* Keep the original character if it's in CJK range */
160	                  if (cp >= 0x4e00 && cp <= 0x9fa5)
161	                    {
162	                      dst[di++] = s[0];
163	                      dst[di++] = s[1];
164	                      dst[di++] = s[2];
165	                    }
166	                  else
167	                    {
168	                      /* Unknown char: skip */
169	                    }
170	                  s += 3;
171	                  continue;
172	                }
173	            }
174	
175	          /* Write replacement string */
176	          while (*r && di < dstsize - 1)
177	            {
178	              dst[di++] = *r++;
179	            }
180	
181	          s += 3;
182	        }
183	      /* 2-byte UTF-8: U+0080 .. U+07FF (skip, not CJK) */
184	      else if (s[0] >= 0xc0 && s[0] < 0xe0 && s[1] >= 0x80)
185	        {
186	          s += 2;
187	        }
188	      /* ASCII */
189	      else if (s[0] < 0x80)
190	        {
191	          dst[di++] = *s++;
192	        }
193	      else
194	        {
195	          /* Invalid UTF-8 byte, skip */
196	          s++;
197	        }
198	    }
199	
200	  dst[di] = '\0';
201	}
