218	/* Uplink worker: capture Opus frames and send as binary frames for the
219	 * given number of seconds.
220	 */
221	static void *uplink_worker(void *arg)
222	{
223	  struct uplink_ctx_s *uc = arg;
224	  struct xiaozhi_app_s *app = uc->app;
225	  uint8_t frame[XZ_OPUS_MAX];
226	  int frames = 0;
227	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
228	
229	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
230	         target_frames, uc->seconds);
231	
232	  
233	  printf("[xiaozhi] app->ws_connected %d\n", app->ws_connected);
234	
235	  while (frames < target_frames && app->ws_connected)
236	    {
237	      printf("[xiaozhi] in while show, frames=%d, target=%d, connected=%d\n",
238	             frames, target_frames, app->ws_connected);
239	      ssize_t n = xiaozhi_audio_read_opus(app->audio, frame, sizeof(frame));
240	      printf("[xiaozhi] read_opus returned: %zd\n", n);
241	      if (n < 0)
242	        {
243	          printf("[xiaozhi] uplink read err: %zd\n", n);
244	          break;
245	        }
246	
247	      if (n > 0)
248	        {
249	          /* Debug: hex dump first Opus frames for format verification. */
250	          if (frames < 3)
251	            {
252	              printf("[xiaozhi] opus frame[%d] len=%zd\n", frames, n);
253	              for (ssize_t i = 0; i < n && i < 32; i++)
254	                {
255	                  printf("%02x ", frame[i]);
256	                }
257	              printf("\n");
258	            }
259	
260	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
261	          if (ret != 0)
262	            {
263	              printf("[xiaozhi] uplink send err: %d\n", ret);
264	              break;
265	            }
266	
267	          frames++;
268	        }
269	    }
270	
271	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
272	  return NULL;
273	}
