275	/* Receive worker: parse server messages and feed TTS audio to the player.
276	 * Runs until ws is closed or a stop condition.
277	 */
278	static void recv_loop(struct xiaozhi_app_s *app, int max_ms,
279	                      bool stop_on_hello)
280	{
281	  int waited = 0;
282	
283	  while (app->ws_connected && waited < max_ms)
284	    {
285	      const uint8_t *payload;
286	      size_t plen;
287	      bool is_binary;
288	      int ret;
289	
290	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
291	      if (ret != 0)
292	        {
293	          app->ws_connected = false;
294	          break;
295	        }
296	
297	      if (is_binary)
298	        {
299	          printf("[xiaozhi] <<< binary frame: %zu bytes\n", plen);

300	          /* Server TTS Opus frame -> feed to player. */
301	          if (app->tts_playing)
302	            {
303	              int wret = xiaozhi_audio_write_opus(app->audio,
304	                                                  payload, plen);
305	              if (wret < 0)
306	                {
307	                  printf("[xiaozhi] TTS write failed (%d), "
308	                         "stopping playback\n", wret);
309	                  app->tts_playing = false;
310	                  xiaozhi_audio_stop_playback(app->audio);
311	                  break;
312	                }
313	            }
314	
315	          waited += 60;
316	          continue;
317	        }
318	
319	      /* Text frame: parse JSON. */
320	      {
321	        char *json = malloc(plen + 1);
322	        if (json == NULL)
323	          {
324	            continue;
325	          }
326	
327	        memcpy(json, payload, plen);
328	        json[plen] = '\0';
329	
330	        cJSON *root = cJSON_Parse(json);
331	        if (root != NULL)
332	          {
333	            /* Print all received text messages for debugging. */
334	            printf("[xiaozhi] <<< recv: %s\n", json);
335	
336	            cJSON *type = cJSON_GetObjectItem(root, "type");
337	            const char *tstr = cJSON_IsString(type) ?
338	              type->valuestring : "";
339	
340	            if (strcmp(tstr, "stt") == 0)
341	              {
342	                cJSON *text = cJSON_GetObjectItem(root, "text");
343	                const char *s = text ? text->valuestring : "?";
344	                printf("[xiaozhi] <<< STT: \"%s\"\n", s);
345	                app->got_stt = true;
346	                sanitize_text(app->stt_text, sizeof(app->stt_text), s);
347	              }
348	            else if (strcmp(tstr, "llm") == 0)
349	              {
350	                cJSON *text = cJSON_GetObjectItem(root, "text");
351	                printf("[xiaozhi] <<< LLM: \"%s\"\n",
352	                       text ? text->valuestring : "?");
353	              }
354	            else if (strcmp(tstr, "mcp") == 0)
355	              {
356	                cJSON *mcp_payload = cJSON_GetObjectItem(root, "payload");
357	                if (cJSON_IsObject(mcp_payload))
358	                  {
359	                    xiaozhi_mcp_handle_message(&app->ws,
360	                                               app->session_id,
361	                                               mcp_payload);
362	                  }
363	              }
364	            else if (strcmp(tstr, "tts") == 0)
365	              {
366	                cJSON *state = cJSON_GetObjectItem(root, "state");
367	                const char *sstr = cJSON_IsString(state) ?
368	                  state->valuestring : "";
369	
370	                if (strcmp(sstr, "start") == 0)
371	                  {
372	                    int pret = xiaozhi_audio_start_playback(app->audio);
373	                    if (pret == 0)
374	                      {
375	                        app->tts_playing = true;
376	                        app->state = XZ_STATE_PLAYING;
377	                      }
378	
379	                    printf("[xiaozhi] <<< TTS start (player=%s)\n",
380	                           pret == 0 ? "ok" : "failed");
381	                  }
382	                else if (strcmp(sstr, "stop") == 0)
383	                  {
384	                    app->tts_playing = false;
385	                    printf("[xiaozhi] <<< TTS stop\n");
386	                    xiaozhi_audio_stop_playback(app->audio);
387	                    cJSON_Delete(root);
388	                    free(json);
389	                    break;   /* end of this turn */
390	                  }
391	                else if (strcmp(sstr, "sentence_start") == 0)
392	                  {
393	                    cJSON *text = cJSON_GetObjectItem(root, "text");
394	                    const char *s = text ? text->valuestring : "?";
395	                    printf("[xiaozhi] <<< TTS: \"%s\"\n", s);
396	                    app->tts_sentences++;
397	                    sanitize_text(app->tts_text, sizeof(app->tts_text), s);
398	                  }
399	              }
400	            else if (strcmp(tstr, "goodbye") == 0)
401	              {
402	                printf("[xiaozhi] <<< goodbye\n");
403	                app->ws_connected = false;
404	                cJSON_Delete(root);
405	                free(json);
406	                break;
407	              }
408	            else if (strcmp(tstr, "hello") == 0)
409	              {
410	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
411	                if (cJSON_IsString(sid))
412	                  {
413	                    strncpy(app->session_id, sid->valuestring,
414	                            sizeof(app->session_id) - 1);
415	                    app->session_id[sizeof(app->session_id) - 1] = '\0';
416	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
417	                           app->session_id);
418	                  }
419	
420	                /* In the connect phase we only need the hello response to
421	                 * obtain the session_id; bail out so we don't block here
422	                 * waiting for server audio that never comes before we've
423	                 * sent listen:start. The server also times out (~10s) if
424	                 * it doesn't see a listen request soon after hello.
425	                 */
426	                if (stop_on_hello)
427	                  {
428	                    cJSON_Delete(root);
429	                    free(json);
430	                    return;
431	                  }
432	              }
433	            else
434	              {
435	                /* Print full message for debugging unknown types (e.g. error). */
436	                char *out = cJSON_PrintUnformatted(root);
437	                printf("[xiaozhi] <<< %s\n", out ? out : tstr);
438	                if (out)
439	                  {
440	                    free(out);
441	                  }
442	              }
443	
444	            cJSON_Delete(root);
445	          }
446	        else
447	          {
448	            printf("[xiaozhi] <<< (parse err) %.*s\n",
449	                   (int)plen, (const char *)payload);
450	          }
451	
452	        free(json);
453	      }
454	
455	      waited += 60;
456	    }
457	}
