459	/* Dialog thread: runs the full OTA -> dialog flow off the main (UI) thread.
460	 */
461	static void *dialog_thread(void *arg)
462	{
463	  struct xiaozhi_app_s *app = arg;
464	  struct xiaozhi_ota_config_s ota;
465	  const char *mac = XIAOZHI_MAC_DEFAULT;
466	  char client_id[40];
467	  int ret;
468	
469	  snprintf(client_id, sizeof(client_id),
470	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
471	
472	  /* Init audio subsystem (creates Opus encoder). */
473	  app->audio = xiaozhi_audio_init();
474	  if (app->audio == NULL)
475	    {
476	      printf("[xiaozhi] audio init failed\n");
477	      app->state = XZ_STATE_ERROR;
478	      return NULL;
479	    }
480	
481	  /* Init MCP server (timer tools). */
482	  mcp_server_init();
483	
484	  /* Step 1: OTA. */
485	  app->state = XZ_STATE_OTA;
486	  printf("[xiaozhi] step 1: OTA\n");
487	  ret = xiaozhi_ota_fetch(mac, &ota);
488	  if (ret != 0)
489	    {
490	      printf("[xiaozhi] OTA failed: %d\n", ret);
491	      app->state = XZ_STATE_ERROR;
492	      return NULL;
493	    }
494	
495	  /* Step 2: wss connect (TLS + ws upgrade). */
496	  app->state = XZ_STATE_CONNECT;
497	  printf("[xiaozhi] step 2: wss connect\n");
498	  ret = xiaozhi_ws_connect(&app->ws, ota.ws_url, ota.ws_token, mac,
499	                           client_id);

500	  if (ret != 0)
501	    {
502	      printf("[xiaozhi] ws connect failed: %d\n", ret);
503	      app->state = XZ_STATE_ERROR;
504	      return NULL;
505	    }
506	
507	  app->ws_connected = true;
508	
509	  /* Step 3: send the hello handshake, then wait for the server's hello
510	   * response which carries the session_id. The server times out (~10s)
511	   * if it never receives a hello, so we must send ours first.
512	   */
513	  printf("[xiaozhi] step 3: send hello + wait hello response\n");
514	  {
515	    cJSON *hello = cJSON_CreateObject();
516	    cJSON_AddStringToObject(hello, "type", "hello");
517	    cJSON_AddNumberToObject(hello, "version", 3);
518	    cJSON_AddStringToObject(hello, "transport", "websocket");
519	
520	    cJSON *ap = cJSON_CreateObject();
521	    cJSON_AddStringToObject(ap, "format", "opus");
522	    cJSON_AddNumberToObject(ap, "sample_rate", 16000);
523	    cJSON_AddNumberToObject(ap, "channels", 1);
524	    cJSON_AddNumberToObject(ap, "frame_duration", 60);
525	    cJSON_AddItemToObject(hello, "audio_params", ap);
526	
527	    cJSON *features = cJSON_CreateObject();
528	    cJSON_AddItemToObject(hello, "features", features);
529	    xiaozhi_mcp_add_features(features);
530	
531	    char *hello_str = cJSON_PrintUnformatted(hello);
532	    printf("[xiaozhi] >>> hello json: %s\n", hello_str ? hello_str : "null");
533	    if (hello_str)
534	      {
535	        free(hello_str);
536	      }
537	    ret = send_json(app, hello);
538	    cJSON_Delete(hello);
539	    if (ret != 0)
540	      {
541	        printf("[xiaozhi] hello send failed: %d\n", ret);
542	        app->state = XZ_STATE_ERROR;
543	        goto out;
544	      }
545	  }
546	
547	  /* Receive the server hello response to get session_id. stop_on_hello
548	   * returns immediately once we have it, so we don't block waiting for
549	   * audio the server won't send before listen:start.
550	   */
551	  recv_loop(app, 5000, true);
552	  if (app->session_id[0] == '\0')
553	    {
554	      printf("[xiaozhi] no session_id, abort\n");
555	      app->state = XZ_STATE_ERROR;
556	      goto out;
557	    }
558	
559	  /* Step 4: listen start + capture + listen stop. */
560	  app->state = XZ_STATE_LISTENING;
561	  printf("[xiaozhi] step 4: listen start + capture, session_id=%s\n",
562	         app->session_id);
563	  {
564	    cJSON *listen = cJSON_CreateObject();
565	    cJSON_AddStringToObject(listen, "session_id", app->session_id);
566	    cJSON_AddStringToObject(listen, "type", "listen");
567	    cJSON_AddStringToObject(listen, "state", "start");
568	    cJSON_AddStringToObject(listen, "mode", "manual");
569	    char *json_str = cJSON_PrintUnformatted(listen);
570	    printf("[xiaozhi] >>> listen start json: %s\n", json_str ? json_str : "null");
571	    if (json_str)
572	      {
573	        free(json_str);
574	      }
575	    send_json(app, listen);
576	    cJSON_Delete(listen);
577	  }
578	
579	  ret = xiaozhi_audio_start_capture(app->audio);
580	  if (ret != 0)
581	    {
582	      printf("[xiaozhi] capture start failed: %d\n", ret);
583	      app->state = XZ_STATE_ERROR;
584	      goto out;
585	    }
586	
587	  {
588	    struct uplink_ctx_s uc;
589	    uc.app = app;
590	    uc.seconds = XZ_DIALOG_SECONDS;
591	    uplink_worker(&uc);
592	  }
593	
594	  xiaozhi_audio_stop_capture(app->audio);
595	
596	  /* listen stop. */
597	  {
598	    cJSON *stop = cJSON_CreateObject();
599	    cJSON_AddStringToObject(stop, "session_id", app->session_id);
600	    cJSON_AddStringToObject(stop, "type", "listen");
601	    cJSON_AddStringToObject(stop, "state", "stop");
602	    char *json_str = cJSON_PrintUnformatted(stop);
603	    printf("[xiaozhi] >>> listen stop json: %s\n", json_str ? json_str : "null");
604	    if (json_str)
605	      {
606	        free(json_str);
607	      }
608	    send_json(app, stop);
609	    cJSON_Delete(stop);
610	  }
611	
612	  /* Step 5: receive stt + tts + playback (up to 20s). */
613	  app->state = XZ_STATE_THINKING;
614	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
615	  recv_loop(app, 20000, false);
616	
617	out:
618	  if (app->tts_playing)
619	    {
620	      xiaozhi_audio_stop_playback(app->audio);
621	    }
622	
623	  xiaozhi_audio_deinit(app->audio);
624	  xiaozhi_ws_close(&app->ws);
625	
626	  app->state = XZ_STATE_DONE;
627	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
628	         app->got_stt ? "yes" : "no", app->tts_sentences);
629	
630	  /* Reset state so user can start a new conversation. */
631	  app->dialog_started = false;
632	  app->ws_connected = false;
633	  app->got_stt = false;
634	  app->tts_playing = false;
635	  app->tts_sentences = 0;
636	  memset(app->session_id, 0, sizeof(app->session_id));
637	  memset(app->stt_text, 0, sizeof(app->stt_text));
638	  memset(app->tts_text, 0, sizeof(app->tts_text));
639	
640	  /* Show the start button for the next conversation.
641	   * We can't call LVGL API from dialog_thread (non-LVGL thread), so we set
642	   * a flag and let the LVGL timer callback do the actual widget update.
643	   */
644	  app->show_start_btn = true;
645	
646	  return NULL;
647	}
