649	/* Start button click handler: kicks off the dialog thread on demand.
650	 * The user taps this after WiFi is up, so OTA can reach the server.
651	 */
652	static void start_btn_event_cb(lv_event_t *e)
653	{
654	  struct xiaozhi_app_s *app = &g_app;
655	  LV_UNUSED(e);
656	
657	  if (app->dialog_started)
658	    {
659	      return;   /* already running */
660	    }
661	
662	  app->dialog_started = true;
663	  app->state = XZ_STATE_OTA;
664	
665	  /* Hide the start button once the dialog is launched. */
666	  if (app->start_btn != NULL)
667	    {
668	      lv_obj_add_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
669	    }
670	
671	  pthread_attr_t attr;
672	  pthread_attr_init(&attr);
673	  pthread_attr_setstacksize(&attr, 65536);
674	
675	  int ret = pthread_create(NULL, &attr, dialog_thread, app);
676	  pthread_attr_destroy(&attr);
677	
678	  if (ret != 0)
679	    {
680	      printf("[xiaozhi] dialog thread create failed: %d\n", ret);
681	      app->state = XZ_STATE_ERROR;
682	      app->dialog_started = false;
683	      if (app->start_btn != NULL)
684	        {
685	          lv_obj_clear_flag(app->start_btn, LV_OBJ_FLAG_HIDDEN);
686	        }
687	    }
688	}
