785	/* Timer callback to refresh UI periodically and check MCP timers. */
786	static void ui_refresh_timer_cb(lv_timer_t *timer)
787	{
788	  LV_UNUSED(timer);
789	  ui_refresh(&g_app);
790	
791	  /* Check for expired MCP timers (once per second via the 100ms timer). */
792	  {
793	    static time_t last_timer_check = 0;
794	    time_t now = time(NULL);
795	    if (now > last_timer_check)
796	      {
797	        int expired = mcp_server_check_timers();
798	        if (expired > 0)
799	          {
800	            const char *msg = mcp_server_get_last_expired_message();
801	            printf("[xiaozhi] TIMER expired: %s\n",
802	                   msg ? msg : "(no message)");
803	          }
804	
805	        last_timer_check = now;
806	      }
807	  }
808	}
