201	static void stopwatch_gesture_event_cb(lv_event_t *e)
202	{
203	    lv_obj_t * obj = lv_event_get_user_data(e);
204	    lv_event_code_t code = lv_event_get_code(e);
205	
206	    switch (code)
207	    {
208	    case LV_EVENT_GESTURE:
209	        lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
210	        if (dir == LV_DIR_BOTTOM)
211	        {
212	            LV_LOG_USER(" LOG_DIR_BOTTOM---But do nothing\n");
213	        }
214	        if (dir == LV_DIR_TOP)
215	        {
216	            LV_LOG_USER(" LV_DIR_TOP---But do nothing\n");
217	        }
218	        if (dir == LV_DIR_LEFT)
219	        {
220	            LV_LOG_USER(" LV_DIR_LEFT---But do nothing\n");
221	        }
222	        if (dir == LV_DIR_RIGHT)
223	        {
224	            LV_LOG_USER(" LV_DIR_RIGHT---Exit\n");
225	            exit_stopwatch();
226	            break;
227	        }
228	
229	    default:
230	        break;
231	    }
232	}
