/****************************************************************************
 * MCP Control Functions (thread-safe, called from dialog thread)
 ****************************************************************************/

/* Request the stopwatch to start. If the UI is not visible, it will be
 * created automatically by the timer callback.
 */

void stopwatch_mcp_start(void)
{
  mcp_start_request = true;
}

/* Request the stopwatch to pause. */

void stopwatch_mcp_pause(void)
{
  mcp_pause_request = true;
}

/* Request the stopwatch to reset. */

void stopwatch_mcp_reset(void)
{
  mcp_reset_request = true;
}

/* Get the current elapsed time in milliseconds.
 * This is a thread-safe read of the stopwatch state.
 */

int stopwatch_mcp_get_elapsed_ms(void)
{
  if (stopwatch_running)
    {
      return (int)(stopwatch_elapsed_time +
                   (lv_tick_get() - stopwatch_start_time));
    }

  return (int)stopwatch_elapsed_time;
}

