/* Stopwatch state (single instance). */

struct stopwatch_s
{
  bool     running;            /* true while counting */
  uint32_t start_ms;           /* tick when started/resumed (ms) */
  uint32_t elapsed_ms;         /* accumulated time when paused (ms) */
};

/* Stopwatch helper functions. */

static cJSON *handle_start_stopwatch(cJSON *id);
static cJSON *handle_stop_stopwatch(cJSON *id);
static cJSON *handle_reset_stopwatch(cJSON *id);
static cJSON *handle_get_stopwatch_time(cJSON *id);

/****************************************************************************
 * Stopwatch Functions
 ****************************************************************************/

/* Helper: get current elapsed milliseconds. */

static uint32_t stopwatch_get_elapsed_ms(void)
{
  uint32_t now = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
  if (g_stopwatch.running)
    {
      return g_stopwatch.elapsed_ms + (now - g_stopwatch.start_ms);
    }

  return g_stopwatch.elapsed_ms;
}

/* Helper: format milliseconds as "MM:SS.mmm". */

static void stopwatch_format(uint32_t ms, char *buf, size_t buflen)
{
  uint32_t minutes = ms / 60000;
  uint32_t seconds = (ms % 60000) / 1000;
  uint32_t millis  = ms % 1000;
  snprintf(buf, buflen, "%02lu:%02lu.%03lu",
           (unsigned long)minutes, (unsigned long)seconds,
           (unsigned long)millis);
}

/* Handle "start_stopwatch" tool call. */

static cJSON *handle_start_stopwatch(cJSON *id)
{
  if (g_stopwatch.running)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("秒表已经在运行中"));
      cJSON_AddBoolToObject(result, "isError", false);
      return resp;
    }

  g_stopwatch.start_ms = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
  g_stopwatch.running = true;
  printf("[mcp] stopwatch started\n");

  {
    char text[128];
    cJSON *resp   = reply_result(id);
    cJSON *result = cJSON_GetObjectItem(resp, "result");
    snprintf(text, sizeof(text), "秒表已启动");
    cJSON_AddItemToObject(result, "content", make_text_content(text));
    cJSON_AddBoolToObject(result, "isError", false);
    return resp;
  }
}

/* Handle "stop_stopwatch" tool call. */

static cJSON *handle_stop_stopwatch(cJSON *id)
{
  if (!g_stopwatch.running)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("秒表未在运行"));
      cJSON_AddBoolToObject(result, "isError", false);
      return resp;
    }

  uint32_t now = (uint32_t)clock() * 1000 / CLOCKS_PER_SEC;
  g_stopwatch.elapsed_ms += (now - g_stopwatch.start_ms);
  g_stopwatch.running = false;

  {
    char time_str[16];
    char text[128];
    cJSON *resp   = reply_result(id);
    cJSON *result = cJSON_GetObjectItem(resp, "result");
    stopwatch_format(g_stopwatch.elapsed_ms, time_str, sizeof(time_str));
    snprintf(text, sizeof(text), "秒表已停止，当前时间: %s", time_str);
    printf("[mcp] stopwatch stopped: %s\n", time_str);
    cJSON_AddItemToObject(result, "content", make_text_content(text));
    cJSON_AddBoolToObject(result, "isError", false);
    return resp;
  }
}

/* Handle "reset_stopwatch" tool call. */

static cJSON *handle_reset_stopwatch(cJSON *id)
{
  g_stopwatch.running = false;
  g_stopwatch.elapsed_ms = 0;
  g_stopwatch.start_ms = 0;
  printf("[mcp] stopwatch reset\n");

  {
    cJSON *resp   = reply_result(id);
    cJSON *result = cJSON_GetObjectItem(resp, "result");
    cJSON_AddItemToObject(result, "content",
      make_text_content("秒表已重置为 00:00.000"));
    cJSON_AddBoolToObject(result, "isError", false);
    return resp;
  }
}

/* Handle "get_stopwatch_time" tool call. */

static cJSON *handle_get_stopwatch_time(cJSON *id)
{
  char time_str[16];
  char text[128];
  uint32_t elapsed = stopwatch_get_elapsed_ms();
  cJSON *resp   = reply_result(id);
  cJSON *result = cJSON_GetObjectItem(resp, "result");

  stopwatch_format(elapsed, time_str, sizeof(time_str));
  snprintf(text, sizeof(text), "秒表当前时间: %s (%s)",
           time_str, g_stopwatch.running ? "运行中" : "已暂停");
  cJSON_AddItemToObject(result, "content", make_text_content(text));
  cJSON_AddBoolToObject(result, "isError", false);
  return resp;
}

