/* Timer callback to refresh UI periodically and check MCP timers. */
static void ui_refresh_timer_cb(lv_timer_t *timer)
{
  LV_UNUSED(timer);
  ui_refresh(&g_app);

  /* Check for expired MCP timers (once per second via the 100ms timer). */
  {
    static time_t last_timer_check = 0;
    time_t now = time(NULL);
    if (now > last_timer_check)
      {
        int expired = mcp_server_check_timers();
        if (expired > 0)
          {
            const char *msg = mcp_server_get_last_expired_message();
            printf("[xiaozhi] TIMER expired: %s\n",
                   msg ? msg : "(no message)");
          }

        last_timer_check = now;
      }
  }

  /* Update stopwatch display if running. */
  if (g_app.stopwatch_label != NULL)
    {
      uint32_t elapsed_ms = 0;
      int running = mcp_server_get_stopwatch_state(&elapsed_ms);

      if (running || elapsed_ms > 0)
        {
          uint32_t minutes = elapsed_ms / 60000;
          uint32_t seconds = (elapsed_ms % 60000) / 1000;
          uint32_t millis  = elapsed_ms % 1000;
          char buf[16];
          snprintf(buf, sizeof(buf), "%02lu:%02lu.%03lu",
                   (unsigned long)minutes, (unsigned long)seconds,
                   (unsigned long)millis);
          lv_label_set_text(g_app.stopwatch_label, buf);
          lv_obj_clear_flag(g_app.stopwatch_label, LV_OBJ_FLAG_HIDDEN);
        }
      else
        {
          lv_obj_add_flag(g_app.stopwatch_label, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

