1	/****************************************************************************
2	 * apps/examples/tswatch/xiaozhi_voice/xiaozhi_mcp.c
3	 *
4	 * MCP (Model Context Protocol) client for the tswatch build.
5	 * In-process version: calls mcp_server_handle_request() directly instead
6	 * of spawning a subprocess (no posix_spawn/pipe needed).
7	 *
8	 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
9	 *
10	 *   { "type": "mcp", "payload": <jsonrpc request> }
11	 *
12	 * This module processes the request directly and sends back:
13	 *
14	 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
15	 *
16	 * SPDX-License-Identifier: Apache-2.0
17	 ****************************************************************************/
18	
19	#include <nuttx/config.h>
20	
21	#include <stdio.h>
22	#include <stdlib.h>
23	#include <string.h>
24	#include <stdbool.h>
25	
26	#include <netutils/cJSON.h>
27	
28	#include "xiaozhi_mcp.h"
29	#include "mcp_server.h"
30	
31	/****************************************************************************
32	 * Private Functions
33	 ****************************************************************************/
34	
35	/* Wrap a JSON-RPC response in an "mcp" frame and send it to the cloud. */
36	
37	static void mcp_send_response(struct xiaozhi_ws_s *ws,
38	                              const char *session_id,
39	                              cJSON *resp)
40	{
41	  cJSON *frame = cJSON_CreateObject();
42	  cJSON_AddStringToObject(frame, "type", "mcp");
43	  cJSON_AddStringToObject(frame, "session_id", session_id);
44	  cJSON_AddItemToObject(frame, "payload", resp);  /* frame owns resp */
45	
46	  char *j = cJSON_PrintUnformatted(frame);
47	  if (j != NULL)
48	    {
49	      xiaozhi_ws_send_text(ws, j, strlen(j));
50	      free(j);
51	    }
52	
53	  cJSON_Delete(frame);
54	}
55	
56	/* Send a JSON-RPC error response back to the cloud. */
57	
58	static void mcp_send_error(struct xiaozhi_ws_s *ws,
59	                           const char *session_id,
60	                           cJSON *id, int code, const char *message)
61	{
62	  cJSON *resp = cJSON_CreateObject();
63	  cJSON *err  = cJSON_CreateObject();
64	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
65	  if (id != NULL)
66	    {
67	      cJSON_AddItemReferenceToObject(resp, "id", id);
68	    }
69	
70	  cJSON_AddItemToObject(resp, "error", err);
71	  cJSON_AddNumberToObject(err, "code", code);
72	  cJSON_AddStringToObject(err, "message", message);
73	
74	  mcp_send_response(ws, session_id, resp);
75	}
76	
77	/****************************************************************************
78	 * Public Functions
79	 ****************************************************************************/
80	
81	void xiaozhi_mcp_add_features(cJSON *features)
82	{
83	  if (features == NULL)
84	    {
85	      return;
86	    }
87	
88	  cJSON_AddBoolToObject(features, "mcp", true);
89	}
90	
91	void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
92	                                const char *session_id,
93	                                cJSON *payload)
94	{
95	  cJSON *method = cJSON_GetObjectItem(payload, "method");
96	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
97	
98	  if (mstr == NULL)
99	    {
100	      printf("[xiaozhi] mcp: payload has no method\n");
101	      return;
102	    }
103	
104	  printf("[xiaozhi] mcp: handling method=%s\n", mstr);
105	
106	  /* Process the request directly via the in-process MCP server. */
107	
108	  cJSON *resp = mcp_server_handle_request(payload);
109	  if (resp == NULL)
110	    {
111	      /* Notification (no id) — nothing to send back. */
112	
113	      return;
114	    }
115	
116	  mcp_send_response(ws, session_id, resp);
117	}
